  FT["PH-H6191"] = {"id":"PH-H6191","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7710_1994.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Boac市","en":"An Act Converting the Cawit High School to Cawit National Comprehensive High School in the Municipality of Boac, Province of Marinduque, and Appropriating Funds for the Purpose","orig":"An Act Converting the Cawit High School to Cawit National Comprehensive High School in the Municipality of Boac, Province of Marinduque, and Appropriating Funds for the Purpose"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7710","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7710_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6191-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Cawit High School is hereby converted to Cawit National Comprehensive High School in the Municipality of Boac, Province of Marinduque."}},{"id":"PH-H6191-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Cawit High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6191-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88"};
  FT["PH-H6192"] = {"id":"PH-H6192","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7711_1994.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省塔纳万市镇基灵描笼涯基灵中学的名称变更为基灵国立中学的法案","en":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School","orig":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7711","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7711_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6192-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Kiling High School in Tanauan, Leyte, is hereby changed to Kiling National High School."}},{"id":"PH-H6192-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6193"] = {"id":"PH-H6193","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7712_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将莱特省塔纳万市镇Kiling描笼涯的Kiling中学更名为Kiling国立中学的法案","en":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School","orig":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7712","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7712_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6193-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing municipal high school in the Municipality of Jose P. Rizal, Province of Palawan, is hereby converted into a national high school, to be known as the Jose P. Rizal National High School, as separate and distinct from the Narra National High School, including the transfer of the properties thereby."}},{"id":"PH-H6193-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such orders, rules and circulars as may be necessary to implement the provisions of this Act."}},{"id":"PH-H6193-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Rizal Municipal High School under Narra National High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6193-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Kiling High School in Barangay Kiling, Municipality of Tanauan, Province of Leyte, to Kiling National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
