  FT["PH-H6195"] = {"id":"PH-H6195","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7714_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Aborlan市","en":"An Act Converting the Aborlan High School in the Municipality of Aborlan, Province of Palawan, Into a National High School, to Be Known as the Aborlan National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Aborlan High School in the Municipality of Aborlan, Province of Palawan, Into a National High School, to Be Known as the Aborlan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7714","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7714_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6195-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Aborlan High School in the Municipality of Aborlan, Province of Palawan, is hereby converted into a national high school, to be known as the Aborlan National High School, separate and distinct from the Plaridel National High School."}},{"id":"PH-H6195-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such orders, rules and circulars as may be necessary to implement the provisions of this Act."}},{"id":"PH-H6195-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Aborlan High School under Plaridel National High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6195-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88"};
  FT["PH-H6196"] = {"id":"PH-H6196","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7715_1994.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将宿务省 Asturias 市镇 Looc Norte 描笼涯的中学改设为独立的 Looc Norte 国立中学，并为此拨款","en":"An Act to Convert the Looc Norte Barangay High School in Looc Norte, Asturias, Cebu, Into a National High School, to Be Known as the Looc Norte National High School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Convert the Looc Norte Barangay High School in Looc Norte, Asturias, Cebu, Into a National High School, to Be Known as the Looc Norte National High School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7715","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7715_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6196-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangay High School of BarangayLooc Norte in the Municipality of Asturias, Cebu, is hereby converted into a national high school, to be known as the Looc Norte National High School."}},{"id":"PH-H6196-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon organization of the Looc Norte National High School, all assets, liabilities, personnel, equipment and records of the Looc Norte Barangay High School shall stand transferred to the Looc Norte National High School."}},{"id":"PH-H6196-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education, Culture and Sports is hereby empowered to promulgate such rules and regulations as may be necessary to carry out the purpose of this Act, including the power to reorganize the school, revise its curriculum, and provide for its supervision."}},{"id":"PH-H6196-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6196-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Looc Norte Barangay High School in Looc Norte, Asturias, Cebu, Into a National High School, to Be Known as the Looc Norte National High School, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6197"] = {"id":"PH-H6197","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7716_1994.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"重组增值税制度、扩大税基并加强其管理，为此修订和废止经修正的国家国内税收法典相关条款并为其他目的法案","en":"An Act Restructuring the Value-added Tax (Vat) System, Widening Its Tax Base and Enhancing Its Administration, and for These Purposes Amending and Repealing the Relevant Provisions of the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act Restructuring the Value-added Tax (Vat) System, Widening Its Tax Base and Enhancing Its Administration, and for These Purposes Amending and Repealing the Relevant Provisions of the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7716","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7716_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6197-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 99 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 99. Persons Liable. — Any person who, in the course of trade or business, sells, barters, exchanges, leases goods or properties, renders services, and any person who imports goods shall be liable to the value-added tax (VAT) imposed in Sections 100 to 102 of this Code.\n\"The value-added tax is an indirect tax and the amount of tax may be shifted or passed on to the buyer, transferee or lessee of the goods, properties or services. This rule shall likewise apply to existing contracts of sale or lease of goods, properties or services at the time of the effectivity of this Act.\n\"The phrase 'in the course of trade or business' means the regular conduct or pursuit of a commercial or an economic activity, including transactions incidental thereto, by any person regardless of whether or not the person engaged therein is a non-stock, non-profit private organization (irrespective of the disposition of its net income and whether or not it sells exclusively to members or their guests), or government entity.\n\"The rule of regularity, to the contrary, notwithstanding, services as defined in this Code rendered in the Philippines by nonresident foreign persons shall be considered as being rendered in the course of trade or business.\""}},{"id":"PH-H6197-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 100 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 100. Value-added tax on sale of goods or properties. — (a) Rate and base of tax. — There shall be levied, assessed and collected on every sale, barter or exchange of goods or properties, a value-added tax equivalent to 10% of the gross selling price or gross value in money of the goods or properties sold, bartered or exchanged, such tax to be paid by the seller or transferor.\n\"(1) The term 'goods or properties' shall mean all tangible and intangible objects which are capable of pecuniary estimation and shall include:\n\"(A) Real properties held primarily for sale to customers or held for lease in the ordinary course of trade or business;\n\"(B) The right or the privilege to use patent, copyright, design or model, plan, secret formula or process, goodwill, trademark, trade brand or other like property or right;\n\"(C) The right or the privilege to use in the Philippines of any industrial, commercial or scientific equipment;\n\"(D) The right or the privilege to use motion picture films, films, tapes and discs; and \"(E) Radio, television, satellite transmission and cable television time.\n\"The term 'gross selling price' means the total amount of money or its equivalent which the purchaser pays or is obligated to pay to the seller in consideration of the sale, barter or exchange of the goods or properties, excluding the value-added tax. The excise tax, if any, on such goods or properties shall form part of the gross selling price.\n\"(2) The following sales by VAT-registered persons shall be subject to 0%:\n\"(A) Export sales. — The term 'export sales' means:\n\"(i) The sale and actual shipment of goods from the Philippines to a foreign country, irrespective of any shipping arrangement that may be agreed upon which may influence or determine the transfer of ownership of the goods so exported and paid for in acceptable foreign currency or its equivalent in goods or services, and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP);\n\"(ii) Sale of raw materials or packaging materials to a nonresident buyer for delivery to a resident local export-oriented enterprise to be used in manufacturing, processing, packing or repacking in the Philippines of the said buyer's goods and paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP);\n\"(iii) Sale of raw materials or packaging materials to export-oriented enterprise whose export sales exceed seventy percent (70%) of total annual production;\n\"(iv) Sale of gold to the Bangko Sentral ng Pilipinas (BSP); and \"(v) Those considered export sales under Executive Order No. 226, otherwise known as the Omnibus Investment Code of 1987, and other special laws.\n\"(B) Foreign currency denominated sale. — The phrase 'foreign currency denominated sale' means sale to a nonresident of goods, except those mentioned in Sections 149 and 150, assembled or manufactured in the Philippines for delivery to a resident in the Philippines, paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP).\n\"(C) Sales to persons or entities whose exemption under special laws or international agreements to which the Philippines is a signatory effectively subjects such sales to zero-rate.\n\"(b) Transactions deemed sale. — The following transactions shall be deemed sale:\n\"(1) Transfer, use, or consumption not in the course of business of goods or properties originally intended for sale or for use in the course of business.\n\"(2) Distribution or transfer to:\n\"(A) Shareholders or investors as share in the profits of the VAT-registered persons; or \"(B) Creditors in payment of debt.\n\"(3) Consignment of goods if actual sale is not made within 60 days following the date such goods were consigned.\n\"(4) Retirement from or cessation of business, with respect to inventories of taxable goods existing as of such retirement or cessation.\n\"(c) Changes in cessation of status of a VAT-registered person. — The tax imposed in paragraph (a) of this section shall also apply to goods disposed of or existing as of a certain date if under circumstances to be prescribed in regulations to be promulgated by the Secretary of Finance, the status of a person as a VAT-registered person changes or is terminated.\n\"(d) Determination of the tax. — (1) The tax shall be computed by multiplying the total amount indicated in the invoice by 1/11.\n\"(2) Sales returns, allowances and sales discounts. — The value of goods or properties sold and subsequently returned or for which allowances were granted by a VAT-registered person may be deducted from the gross sales or receipts for the quarter in which a refund is made or a credit memorandum or refund is issued. Sales discount granted and indicated in the invoice at the time of sale and the grant of which does not depend upon the happening of a future event may be excluded from the gross sales within the same quarter it was given.\n\"(3) Authority of the Commissioner to determine the appropriate tax base. — The Commissioner shall, by regulations, determine the appropriate tax base in cases where a transaction is deemed a sale, barter or exchange of goods or properties under paragraph (b) hereof, or where the gross selling price is unreasonably lower than the actual market value.\""}},{"id":"PH-H6197-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 102 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 102. Value-added tax on sale of services and use or lease of properties. — (a) Rate and base of tax. — There shall be levied, assessed and collected, a value-added tax equivalent to 10% of gross receipts derived from the sale or exchange of services, including the use or lease of properties.\n\"The phrase 'sale or exchange of services' means the performance of all kinds of services in the Philippines for others for a fee, remuneration or consideration, including those performed or rendered by construction and service contractors; stock, real estate, commercial, customs and immigration brokers; lessors of property, whether personal or real; warehousing services; lessors or distributors of cinematographic films; persons engaged in milling, processing, manufacturing or repacking goods for others; proprietors, operators or keepers of hotels, motels, resthouses, pension houses, inns, resorts; proprietors or operators of restaurants, refreshment parlors, cafes and other eating places, including clubs and caterers; dealers in securities; lending investors; operators of taxicabs; utility cars for rent or hire driven by the lessees (rent-a-car companies), tourist buses; and other common carriers by land, air, and sea relative to their transport of goods or cargoes; services of franchise grantees of telephone and telegraph, radio and television broadcasting and all other franchise grantees except those under Section 117 of this Code; services of banks, non-bank financial intermediaries and finance companies; and non-life insurance companies (except their crop insurances) including surety, fidelity, indemnity and bonding companies; and similar services regardless of whether or not the performance thereof calls for the exercise or use of the physical or mental faculties. The phrase 'sale or exchange of services' shall likewise include:\n\"(1) The lease or the use of or the right or privilege to use any copyright, patent, design or model, plan, secret formula or process, goodwill, trademark, trade brand or other like property or right;\n\"(2) The lease or the use of, or the right to use of any industrial, commercial or scientific equipment;\n\"(3) The supply of scientific, technical, industrial or commercial knowledge or information;\n\"(4) The supply of any assistance that is ancillary and subsidiary to and is furnished as a means of enabling the application or enjoyment of any such property, or right as is mentioned in subparagraph (2) or any such knowledge or information as is mentioned in subparagraph (3); or \"(5) The supply of services by a nonresident person or his employee in connection with the use of property or rights belonging to, or the installation or operation of any brand, machinery, or other apparatus purchased from such nonresident person;\n\"(6) The supply of technical advice, assistance or services rendered in connection with technical management or administration of any scientific, industrial or commercial undertaking, venture, project or scheme;\n\"(7) The lease of motion picture films, films, tapes and discs; and \"(8) The lease or the use of or the right to use radio, television, satellite transmission and cable television time.\n\"Lease of properties shall be subject to the tax herein imposed irrespective of the place where the contract of lease or licensing agreement was executed if the property is leased or used in the Philippines.\n\"The term 'gross receipts' means the total amount of money or its equivalent representing the contract price, compensation, service fee, rental or royalty, including the amount charged for materials supplied with the services and deposits and advanced payments actually or constructively received during the taxable quarter for the services performed or to be performed for another person, excluding value-added tax.\n\"(b) Transactions subject to zero-rate. — The following services performed in the Philippines by VAT-registered persons shall be subject to 0%:\n\"(1) Processing, manufacturing or repacking goods for other persons doing business outside the Philippines which goods are subsequently exported, where the services are paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP).\n\"(2) Services other than those mentioned in the preceding sub-paragraph, the consideration for which is paid for in acceptable foreign currency and accounted for in accordance with the rules and regulations of the Bangko Sentral ng Pilipinas (BSP).\n\"(3) Services rendered to persons or entities whose exemption under special laws or international agreements to which the Philippines is a signatory effectively subjects the supply of such services to zero rate.\n\"(4) Services rendered to vessels engaged exclusively in international shipping; and \"(5) Services performed by subcontractors and/or contractors in processing, converting, or manufacturing goods for an enterprise whose export sales exceed seventy percent (70%) of total annual production.\n\"(c) Determination of the tax. — The tax shall be computed by multiplying the total amount indicated in the official receipt by 1/11.\""}},{"id":"PH-H6197-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 103 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 103. Exempt transactions. — The following shall be exempt from the value-added tax:\n\"(a) Sale of nonfood agricultural products; marine and forest products in their original state by the primary producer or the owner of the land where the same are produced;\n\"(b) Sale of cotton and cotton seeds in their original state; and copra;\n\"(c) Sale or importation of agricultural and marine food products in their original state, except importation of meat, livestock and poultry of a kind generally used as, or yielding or producing foods for human consumption; and breeding stock and genetic materials therefor.\n\"Products classified under this paragraph and paragraph (a) shall be considered in their original state even if they have undergone the simple processes of preparation or preservation for the market, such as freezing, drying, salting, smoking or stripping. Polished and/or husked rice, corn grits, locally produced raw cane sugar and ordinary salt shall be considered in their original state;\n\"(d) Sale or importation of fertilizers; seeds, seedlings and fingerlings; fish, prawn, livestock and poultry feeds, including ingredients, whether locally produced or imported, used in the manufacture of finished feeds (except specialty feeds for race horses, fighting cocks, aquarium fish, zoo animals and other animals generally considered as pets);\n\"(e) Sale or importation of petroleum products (except lubricating oil, processed gas, grease, wax, and petrolatum) subject to excise tax imposed under Title VI;\n\"(f) Sale or importation of raw materials to be used by the buyer or importer himself in the manufacture of petroleum products subject to excise tax, except lubricating oil, processed gas, grease, wax, and petrolatum;\n\"(g) Importation of passenger and/or cargo vessel of more than five thousand tons, whether coastwise or ocean-going, including engine and spare parts of said vessel to be used by the importer himself as operator thereof;\n\"(h) Importation of personal and household effects belonging to the residents of the Philippines returning from abroad and nonresident citizens coming to resettle in the Philippines: Provided, That such goods are exempt from customs duties under the Tariff and Customs Code of the Philippines;\n\"(i) Importation of professional instruments and implements, wearing apparel, domestic animals, and personal household effects (except any vehicle, vessel, aircraft, machinery, other goods for use in the manufacture and merchandise of any kind in commercial quantity) belonging to persons coming to settle in the Philippines, for their own use and not for sale, barter or exchange, accompanying such persons, or arriving within ninety (90) days before or after their arrival, upon the production of evidence satisfactory to the Commissioner of Internal Revenue, that such persons are actually coming to settle in the Philippines and that the change of residence is bona fide;\n\"(j) Services subject to percentage tax under Title V;\n\"(k) Services by agricultural contract growers and milling for others of palay into rice, corn into grits and sugar cane into raw sugar;\n\"(l) Medical, dental, hospital and veterinary services except those rendered by professionals;\n\"(m) Educational services rendered by private educational institutions, duly accredited by the Department of Education, Culture and Sports, and those rendered by government educational institutions;\n\"(n) Sale by the artist himself of his works of art, literary works, musical compositions and similar creations, or his services performed for the production of such works;\n\"(o) Services rendered by individuals pursuant to an employer-employee relationship;\n\"(p) Services rendered by regional or area headquarters established in the Philippines by multinational corporations which act as supervisory, communications and coordinating centers for their affiliates, subsidiaries or branches in the Asia-Pacific Region and do not earn or derive income from the Philippines;\n\"(q) Transactions which are exempt under special laws, except those granted under Presidential Decree Nos. 66,529,972,1491, and 1590, and non-electric cooperatives under Republic Act No. 6938, or international agreements to which the Philippines is a signatory;\n\"(r) Export sales by persons who are not VAT-registered;\n\"(s) Sale of real properties not primarily held for sale to customers or held for lease in the ordinary course of trade or business or real property utilized for low-cost and socialized housing as defined by Republic Act No. 7279, otherwise known as the Urban Development and Housing Act of 1992, and other related laws;\n\"(t) Sale or lease of goods or properties or the performance of services other than the transactions mentioned in the preceding paragraphs, the gross annual sales and/or receipts do not exceed the amount prescribed in regulations to be promulgated by the President upon the recommendation by the Secretary of Finance which shall not be less than Four hundred eighty thousand pesos (₱480,000) or more than Seven hundred twenty thousand pesos (₱720,000) subject to tax under Section 112 of this Code.\n\"The foregoing exemptions to the contrary notwithstanding, any person whose sale of goods or properties or services which are otherwise not subject to VAT, but who issues a VAT invoice or receipt therefor shall, in addition to his liability to other applicable percentage tax, if any, be liable to the tax imposed in Section 100 or 102 without the benefit of input tax credit, and such tax shall not also be recognized as input tax credit to the purchaser under Section 104, all of this Code.\""}},{"id":"PH-H6197-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 104 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 104. Tax Credits. — (a) Creditable input tax. — Any input tax evidenced by a VAT invoice or official receipt issued in accordance with Section 108 hereof on the following transactions shall be creditable against the output tax:\n\"(1) Purchase or importation of goods:\n\"(A) For sale; or \"(B) For conversion into or intended to form part of a finished product for sale including packaging materials; or \"(C) For use as supplies in the course of business; or \"(D) For use as materials supplied in the sale of service; or \"(E) For use in trade or business for which deduction for depreciation or amortization is allowed under this Code, except automobiles, aircraft and yachts.\n\"(2) Purchase of services on which a value-added tax has been actually paid.\n\"The input tax on domestic purchase of goods or properties shall be creditable:\n\"(AA) To the purchaser upon consummation of sale and on importation of goods or properties;\n\"(BB) To the importer upon payment of the value-added tax prior to the release of the goods from the custody of the Bureau of Customs.\n\"However, in the case of purchase of services, lease or use of properties the input tax shall be creditable to the purchaser, lessee or licensee upon payment of the compensation, rental, royalty or fee.\n\"A VAT-registered person who is also engaged in transactions not subject to the value-added tax shall be allowed input tax credit as follows:\n\"(A) Total input tax which can be directly attributed to transactions subject to value-added tax; and \"(B) A ratable portion of any input tax which cannot be directly attributed to either activity.\n\"The term 'input tax' means the value-added tax due from or paid by a VAT-registered person in the course of his trade or business on importation of goods or local purchase of goods or services, including lease or use of property, from a VAT-registered person. It shall also include the transitional input tax determined in accordance with Section 105 of this Code.\n\"The term 'output tax' means the value-added tax due on the sale or lease of taxable goods or properties or services by any person registered or required to register under Section 107 of this Code.\n\"(b) Excess output or input tax. — If at the end of the any taxable quarter the output tax exceeds the input tax, the excess shall be paid by the VAT-registered person. If the input tax exceeds the output tax, the excess shall be carried over to the succeeding quarters. Any input tax attributable to the purchase of capital goods or to zero-rated sales by a VAT-registered person may at his option be refunded or credited against other internal revenue taxes, subject to the provisions of Section 106.\n\"(c) Determination of creditable input tax. — The sum of the excess input tax carried over from the preceding month or quarter and the input tax creditable to a VAT-registered person during the taxable month or quarter shall be reduced by the amount of claim for refund or tax credit for value-added tax and other adjustments, such as purchase returns or allowances and input tax attributable to exempt sale.\n\"The claim for tax credit referred to in the foregoing paragraph shall include not only those filed with the Bureau of Internal Revenue (BIR) but also those filed with the other government agencies, such as the Board of Investments (BOI) and the Bureau of Customs (BOC).\""}},{"id":"PH-H6197-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 106 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 106. Refunds or tax credits of creditable input tax. — \"(a) Any VAT-registered person, whose sales are zero-rated or effectively zero-rated, may, within two (2) years after the close of the taxable quarter when the sales were made, apply for the issuance of a tax credit certificate or refund of creditable input tax due or paid attributable to such sales, except transitional input tax, to the extent that such input tax has not been applied against output tax: Provided, however, That in the case of zero-rated sales under Section 100(a)(2)(A)(i), (ii) and (b) and Section 102(b)(1) and (2), the acceptable foreign currency exchange proceeds thereof had been duly accounted for in accordance with the regulations of the Bangko Sentral ng Pilipinas (BSP): Provided further, That where the taxpayer is engaged in zero-rated or effectively zero-rated sale and also in taxable or exempt sale of goods or properties or services, and the amount of creditable input tax due or paid cannot be directly and entirely attributed to any one of the transactions, it shall be allocated proportionately on the basis of the volume of sales.\n\"(b) Capital goods. — A VAT-registered person may apply for the issuance of a tax credit certificate or refund of input taxes paid on capital goods imported or locally purchased, to the extent that such input taxes have not been applied against output taxes. The application may be made only within two (2) years after the close of the taxable quarter when the importation or purchase was made.\n\"(c) Cancellation of VAT-registration. — A person whose registration has been cancelled due to retirement from or cessation of business, or due to changes in or cessation of status under Section 100(c) of this Code may, within two (2) years from the date of cancellation, apply for the issuance of a tax credit certificate for any unused input tax which may be used in payment of his other internal revenue taxes.\n\"(d) Period within which refund or tax credit of input taxes shall be made. — In proper cases, the Commissioner shall grant a refund or issue the tax credit for creditable input taxes within sixty (60) days from the date of submission of complete documents in support of the application filed in accordance with sub-paragraphs (a) and (b) hereof. In case of full or partial denial of the claim for tax refund or tax credit, or the failure on the part of the Commissioner to act on the application within the period prescribed above, the taxpayer affected may, within thirty (30) days from the receipt of the decision denying the claim or after the expiration of the sixty-day period, appeal the decision or the unacted claim with the Court of Tax Appeals.\n\"(e) Manner of giving refund. — Refund shall be made upon warrants drawn by the Commissioner or by his duly authorized representative without the necessity of being countersigned by the Chairman, Commission on Audit, the provisions of the Revised Administrative Code to the contrary notwithstanding: Provided, That refunds under this paragraph shall be subject to post audit by the Commission on Audit.\""}},{"id":"PH-H6197-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 107 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 107. Registration of value-added taxpayers. — (a) In general. — Any person subject to a value—added tax under Sections 100 and 102 of this Code shall register with the appropriate Revenue District Officer and pay an annual registration fee in the amount of One thousand pesos (₱1,000) for every separate or distinct establishment or place of business and every year thereafter on or before the last day of January. Any person just commencing a business subject to the value-added tax must pay the fee before engaging therein.\n\"A person who maintains a head or main office and branches in different places shall register with the Revenue District Office which has jurisdiction over the place wherein the main or head office is located. However, the fee shall be paid to the Revenue District Officer, collection agent, authorized treasurer of the municipality where each place of business or branch is situated.\n\"(b) Persons commencing business. — Any person who expects to realize gross sales or receipts subject to value-added tax in excess of the amount prescribed under Section 103(t) of this Code for the next 12-month period from the commencement of the business shall, within thirty (30) days before the start of the said business, register with the Revenue District Officer who has jurisdiction over his principal place of business and shall pay the annual registration fee prescribed in the preceding paragraph.\n\"(c) Persons becoming liable to the value-added tax. — Any person whose gross sales or receipts in any 12-month period exceeds the amount prescribed under Section 103(t) of this Code for exemption from the value-added tax shall register and pay the annual registration fee prescribed in paragraph (a) of this section within thirty (30) days after the end of the last month of that period, and shall be liable to the value-added tax commencing from the first day of the month following his registration.\n\"(d) Optional registration of exempt person. — Any person whose transactions are exempt from value-added tax under Section 103(t) of this Code, or any person whose transactions are exempt from value-added tax under Section 103(a), (b), (c), and (d) of this Code with respect to his export sales only, may apply for registration as a VAT-registered person not later than ten (10) days before the beginning of the taxable quarter and shall pay the annual registration fee prescribed in sub-paragraph (a) of this section.\n\"In any case, the Commissioner may, for administrative reason, deny any application for registration.\n\"For purposes of this Title , any person registered in accordance with the provisions of this section shall be referred to as 'VAT-registered person.' Each VAT-registered person shall be assigned only one taxpayer's identification number.\n\"(e) Cancellation of Registration. — The registration of any person who ceases to be liable to the value-added tax shall be cancelled by the Commissioner upon filing of an application for cancellation of registration. Any person who opted to be registered under paragraph (d) of this section may, under regulation of the Secretary of Finance, apply for cancellation of such registration.\""}},{"id":"PH-H6197-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 108 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 108. Invoicing and accounting requirements for VAT-registered persons. — (a) Invoicing requirements. — A VAT-registered person shall, for every sale, issue an invoice or receipt. In addition to the information required under Section 238, the following information shall be indicated in the invoice or receipt:\n\"(1) A statement that the seller is a VAT-registered person, followed by his taxpayer's identification number (TIN); and \"(2) The total amount which the purchaser pays or is obligated to pay to the seller with the indication that such amount includes the value-added tax.\n\"(b) Accounting requirements. — Notwithstanding the provision of Section 223, all persons subject to the value-added tax under Sections 100 and 102 shall, in addition to the regular accounting records required, maintain a subsidiary sales journal and subsidiary purchase journal on which the daily sales and purchases are recorded. The subsidiary journals shall contain such information as may be required by the Secretary of Finance.\""}},{"id":"PH-H6197-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 110(c) of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"(c) Withholding of Creditable Value-Added Tax. — The government or any of its political subdivisions, instrumentalities or agencies, including government-owned or controlled corporations (GOCCs) shall, before making payment on account of its purchase of goods from sellers and services rendered by contractors which are subject to the value-added tax imposed in Sections 100 and 102 of this Code, deduct and withhold the value-added tax due at the rate of three percent (3%) of the gross payment for the purchase of goods and six percent (6%) on gross receipts for services rendered by contractors on every sale or installment payment which shall be creditable against the value-added tax liability of the seller or contractor: Provided, however, That the payment for lease or use of properties or property rights to nonresident owners shall be subject to ten percent (10%) withholding tax at the time of payment. For this purpose, the payor or person in control of the payment shall be considered as the withholding agent.\""}},{"id":"PH-H6197-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 112 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 112. Tax on persons exempt from value-added tax (VAT). — Any person whose sales or receipts are exempt under Section 103(t) of this Code from the payment of value-added tax and who is not a VAT-registered person shall pay a tax equivalent to three percent (3%) upon the effectivity of this Act and four percent (4%) two (2) years thereafter, of his gross quarterly sales or receipts.\""}},{"id":"PH-H6197-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 115 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 115. Percentage tax on carriers and keepers of garages. — Keepers of garages, and common carriers by land, air or water for the transport of passengers, except owners of bancas, and owners of animal-drawn two-wheeled vehicles, shall pay a tax equivalent to three per centum (3%) of their quarterly gross receipts.\n\"The gross receipts of common carriers derived from their incoming and outgoing freight shall not be subjected to the local taxes imposed under Republic Act No. 7160, otherwise known as the Local Government Code of 1991.\n\"In computing the percentage tax provided in this section, the following shall be considered the minimum quarterly gross receipts in each particular case:\n\"Jeepney for hire -\n1. Manila and other cities ₱2,400\n2. Provincial ₱1,200 \"Public utility bus - Not exceeding 30 passengers ₱3,600 Exceeding 30 but not exceeding 50 passengers ₱6,000 Exceeding 50 passengers ₱7,200 \"Taxis -\n1. Manila and other cities ₱3,600\n2. Provincial ₱2,400 Car for hire (w/ chauffeur) ₱3,000 Car for hire (w/out chauffeur) ₱1,800\""}},{"id":"PH-H6197-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 117 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 117. Tax on franchises. — Any provision of general or special law to the contrary notwithstanding, there shall be levied, assessed and collected in respect to all franchises on electric, gas and water utilities a tax of two percent (2%) on the gross receipts derived from the business covered by the law granting the franchise.\n\"The grantee shall file the return with, and pay the tax due thereon to, the Commissioner of Internal Revenue or his duly authorized representative in accordance with the provisions of Section 125 of this Code and the return shall be subject to audit by the Bureau of Internal Revenue, any provision of any existing law to the contrary notwithstanding.\""}},{"id":"PH-H6197-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The first paragraph of Section 121 of this Code is hereby further amended to read as follows:\n\"Section 121. Tax on Life Insurance Premium. — There shall be collected from every person, company, or corporation (except purely cooperative companies or associations) doing life insurance business of any sort in the Philippines a tax of five per centum (5%) of the total premium collected, whether such premiums are paid in money, notes, credits or any substitute for money; but premiums refunded within six months after payment on account of rejection of risk or returned for other reason to a person insured shall not be included in the taxable receipts; nor shall any tax be paid upon reinsurance by a company that has already paid the tax; nor upon premiums collected or received by any branch of a domestic corporation, firm or association doing business outside the Philippines on account of any life insurance of the insured who is a nonresident, if any tax on such premium is imposed by the foreign country where the branch is established nor upon premiums collected or received on account of any reinsurance, if the insured of personal insurance resides outside the Philippines, if any tax on such premiums is imposed by the foreign country where the original insurance has been issued or perfected; nor upon that portion of the premiums collected or received by the insurance companies on variable contracts (as defined in Sec. 232(2) of Presidential Decree No. 612), in excess of the amounts necessary to insure the lives of the variable contract workers.\""}},{"id":"PH-H6197-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section 236 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 236. Indication of taxpayer identification number (TIN). — For tax identification purposes, any person required under the authority of this Code, to make, render, or file a return, statement, or a document, shall be supplied with or assigned a taxpayer identification number (TIN) which shall be indicated on such return, statement or document.\n\"Any person who shall secure more than one TIN or who fails to indicate his correct TIN as required in the foregoing paragraph, shall be criminally liable under the provisions of Section 274 of this Code.\""}},{"id":"PH-H6197-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Section 237 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 237. Registration of name or style with the revenue district officer or collection agent. — Every person, other than persons required to be registered under the provisions of Section 107 engaged in any business shall, on or before the commencement of his business, or whenever he transfers to another revenue district, register with the Revenue District Officer concerned within 10 days from the commencement of business or transfer and shall pay the annual registration fee in the amount of One thousand pesos (₱1,000) for every separate or distinct establishment or place of business and every year thereafter on or before the last day of January. The fee shall be paid to the Revenue District Officer, collection agent, authorized treasurer of the municipality where each place of business or branch is situated. In cities or municipalities where no revenue district officer is stationed, such person shall register and pay the fee prescribed herein with the collection agent. The registration shall contain his name or style, place of residence, business, the place where such business is carried on, and such other information as may be required by the Commissioner in the form prescribed therefor. In the case of a firm, the names and residences of the various persons constituting the same shall also be registered. The Commissioner, after taking into consideration the volume of sales, financial condition and other relevant factors, may require the registrant to guarantee the payment of his taxes by way of advance payment, or the posting or filing of a security, guarantee or collateral acceptable to the Commissioner.\""}},{"id":"PH-H6197-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Section 238 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 238. Issuance of receipts or sales or commercial invoices. — All persons subject to an internal revenue tax shall, for each sale or transfer of merchandise or for services rendered valued at P25 or more, issue duly registered receipts or sales or commercial invoices, prepared at least in duplicate, showing the date of transaction, quantity, unit cost and description of merchandise or nature of service: Provided, however, That in the case of sales, receipts or transfers in the amount of P100 or more, or, regardless of amount, where the sale or transfer is made by a person liable to value-added tax to another person also liable to value-added tax; or, where the receipt is issued to cover payment made as rentals, commissions, compensations or fees, receipts or invoices shall be issued which shall show the name, business style, if any, and address of the purchaser, customer, or client: Provided, further, That where the purchaser is a VAT-registered person, in addition to the information herein required, the invoice or receipt shall further show the taxpayer's identification number of the purchaser.\n\"The original of each receipt or invoice shall be issued to the purchaser, customer or client at the time the transaction is effected, who, if engaged in business or in the exercise of profession, shall keep and preserve the same in his place of business for a period of 3 years from the close of the taxable year in which such invoice or receipt was issued, while the duplicate shall be kept and preserved by the issuer, also in his place of business, for a like period.\n\"The Commissioner may, in meritorious cases, exempt any person subject to an internal revenue tax from compliance with the provisions of this section.\""}},{"id":"PH-H6197-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity of the Imposition of VAT on Certain Goods, Properties and Services. — The value-added tax shall be levied, assessed and collected on the following, two (2) years after the effectivity of this Act:\n(a) Services performed in the exercise of profession or calling subject to the professional tax under the Local Government Code or Republic Act No. 7160, and professional services performed by registered general professional partnerships; actors, actresses, talents, singers and emcees; radio and television broadcasters, choreographers; musical, radio, movie, television and stage directors; and professional athletes;\n(b) Services rendered by banks, non-bank financial intermediaries, finance companies and other financial intermediaries not performing quasi-banking functions;\n(c) Freight services rendered by international cargo vessels; and\n(d) The lease or use of sports facilities and equipment by amateur players, as provided under Republic Act No. 6847, except sports facilities and equipment which are exclusively or mainly for the private use of shareholders or members of the club or organization which owns or operates such sports facilities and equipment.\nPrior to their inclusion in the coverage of the value-added tax, the above services shall continue to pay the applicable tax prescribed under the present provisions of the National Internal Revenue Code, as amended.\nHowever, when public interest so requires, the President, taking into account the impact on the prices of goods and services, may, upon the recommendation of the Secretary of Finance, exclude any of the above services from the coverage of the value-added tax: Provided, however, That in the event of the exclusion of any of the above services the existing applicable tax under the provisions of the National Internal Revenue Code, as amended, shall continue to be paid on the service so excluded."}},{"id":"PH-H6197-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Tax Administration Development Fund. — For the effective implementation of this Act, there is hereby created a Tax Administration Development Fund to be sourced from five percent (5%) of the increase in value-added tax collections for 1995 over that of the immediately preceding year and annually thereafter for a period of four (4) years five percent (5%) of the increase over the collection of the preceding year. Such amount which shall be retained by the Bureau of Internal Revenue shall be considered receipts automatically appropriated for the first year. Disbursements from this fund shall be subject to such rules and guidelines as may be promulgated by the Department of Finance upon recommendation of the Commissioner of Internal Revenue. These funds shall not be used for the purchase of vehicles, the payment of salaries and incentives, creation of regular positions, and construction of buildings and offices."}},{"id":"PH-H6197-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Rules and Regulations. — For the effective implementation of this Act, the Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations within ninety (90) days from effectivity hereof."}},{"id":"PH-H6197-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Repealing Clauses. — The provisions of any special law relative to the rate of franchise taxes are hereby expressly repealed. Sections 113, 114, and 116 of the National Internal Revenue Code are hereby repealed.\nParagraphs (c), (d), and (e) of Article 39 of Executive Order No. 226, otherwise known as the Omnibus Investment Code of 1987, are hereby repealed: Provided, however, That the benefits and incentives under said paragraphs shall continue to be enjoyed by enterprises registered with the Board of Investments before the effectivity of this Act.\nUnless otherwise excluded by the President pursuant to Section 17 hereof, Sections 119 and 120 of the National Internal Revenue Code shall be repealed upon the expiration of two (2) years from the effectivity of this Act. During the period that the freight services rendered by international cargo vessels are not covered by the value-added tax imposed under this Act, said services shall pay a tax at a rate of three per centum (3%) of their quarterly gross receipts derived from outgoing cargoes.\nAll other laws, orders, issuances, rules and regulations or parts thereof inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6197-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, May 5, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Restructuring the Value-added Tax (Vat) System, Widening Its Tax Base and Enhancing Its Administration, and for These Purposes Amending and Repealing the Relevant Provisions of the National Internal Revenue Code, as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6198"] = {"id":"PH-H6198","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7717_1994.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"关于税买卖的法","en":"An Act Imposing a Tax on the Sale, Barter or Exchange of Shares of Stock Listed and Traded Through the Local Stock Exchange or Through Initial Public Offering, Amending for the Purpose the National Internal Revenue Code, as Amended, By Inserting a New Section and Repealing Certain Subsections Thereof","orig":"An Act Imposing a Tax on the Sale, Barter or Exchange of Shares of Stock Listed and Traded Through the Local Stock Exchange or Through Initial Public Offering, Amending for the Purpose the National Internal Revenue Code, as Amended, By Inserting a New Section and Repealing Certain Subsections Thereof"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7717","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7717_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6198-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A new section is hereby inserted in the National Internal Revenue Code, as amended, as Section 124-A, which shall read as follows:\nSection 124-A. Tax on Sale, Barter or Exchange of Shares of Stock Listed and Traded through the Local Stock Exchange or through Initial Public Offering. - (a) Tax on sale, barter or exchange of shares of stock listed and traded through the local stock exchange. - There shall be levied, assessed, and collected on every sale, barter, exchange, or other disposition of shares of stock listed and traded through the local stock exchange other than the sale by a dealer in securities, a tax at the rate of one-half of one percent (1/2 of 1%) of the gross selling price or gross value in money of the shares of stock sold, bartered, exchanged, or otherwise disposed which shall be paid by the seller or transferor.\nIt shall be the duty of every stock broker who effected the sale subject to the tax imposed herein to collect the tax and remit the same to the Bureau of Internal Revenue in five (5) banking days from the date of collection thereof and to submit on Mondays of each week to the secretary of the stock exchange, of which he is a member, a true and complete return which shall contain a declaration of all the transactions effected through him during the preceding week and of taxes collected by him and turned over to the Bureau of Internal Revenue.\n(b) Tax on shares of stock sold or exchanged through initial public offering. - There shall be levied, assessed, and collected on every sale, barter, exchange, or other disposition through initial public offering of shares of stock in closely held corporations, as defined herein, a tax at the rates provided hereunder based on the gross selling price or gross value in money of the shares of stock sold, bartered, exchanged, or otherwise disposed in accordance with the proportion of shares of stock sold, bartered, exchanged, or otherwise disposed to the total outstanding shares of stock after the listing in the local stock exchange:\n33 1/3% or below 4% Over 33 1/3% but below 50% 2% Over 50% 1% The tax herein imposed shall be paid by the issuing corporation in primary offering or by the seller in secondary offering.\nFor purposes of this section, the term \"closely held corporation\" means any corporation at least fifty percent (50%) in value of the outstanding capital stock or at least fifty percent (50%) of the total combined voting power of all classes of stock entitled to vote is owned directly or indirectly by or for not more than twenty (20) individuals.\nFor purposes of determining whether the corporation is a closely held corporation, insofar as such determination is based on stock ownership, the following rules shall be applied:\n(1) Stock not owned by individuals. - Stock owned directly or indirectly by or for a corporation, partnership, estate or trust shall be considered as being owned proportionately by its shareholders, partners, or beneficiaries.\n(2) Family and partnership ownerships. - An individual shall be considered as owning the stock owned, directly or indirectly, by or for his family, or by or for his partner. For purposes of this paragraph, the family of an individual includes only his brothers and his sisters (whether by the whole or half-blood), spouse, ancestors, and lineal descendants.\n(3) Option. - If any person has an option to acquire stock, such stock shall be considered as owned by such person. For purposes of this paragraph, an option to acquire such an option and each one of a series of options shall be considered as an option to acquire such stock.\n(4) Constructive ownership as actual ownership. - Stock constructively-owned by reason of the application of paragraph or (3) shall, for purposes of applying paragraph (1) or (2), be treated as actually owned by such person; but stock constructively owned by the individual by reason of the application of paragraph hereof shall not be treated as owned by him for purposes of again applying such paragraph in order to make another the constructive owner of such stock.\nIn case of primary offering, the corporate issuer shall file the return and pay the corresponding tax within thirty (30) days from the date of listing of the shares of stock in the local stock exchange. In the case of secondary offering, the provision of subsection (a) of this section shall apply as to the time and manner of the payment of the tax.\n(c) Common provisions. - Any gain derived from the sale, barter, exchange, or other disposition of shares of stock under this section shall be exempt from the tax imposed in Sections 21(d), 24(e)(2), 25(a)(6)(C), and 25(b)(5)(C) of this Code and from the regular individual or corporate income tax. Tax paid under this section shall not be deductible for income tax purposes."}},{"id":"PH-H6198-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For a period of one (1) year after the effectivity of this Act, the tax imposed on the sale, barter, exchange, or other disposition of stock listed and traded through the local stock exchange shall be three-eighths of one percent (3/8 of 1%)."}},{"id":"PH-H6198-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Sections 21(d)(2), 24(e)(2)(B), 25(a)(6)(C)(ii), and 25(b)(5)(C)(ii) of the National Internal Revenue Code, as amended, are hereby repealed."}},{"id":"PH-H6198-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Finance, upon the recommendation of the Commissioner of Internal Revenue, shall within ninety (90) days from the effectivity of this Act promulgate such rules and regulations as may be necessary for the effective implementation hereof."}},{"id":"PH-H6198-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, May 5, 1994."}}],"pack":"ph-p88"};
  FT["PH-H6199"] = {"id":"PH-H6199","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7718_1994.html","fetchedAt":"2026-10-06","articleCount":18,"structureMode":"ARTICLE","title":{"zh":"对第 6957 号共和国法的修改","en":"An Act Amending Certain Sections of Republic Act No. 6957, Entitled \"An Act Authorizing the Financing, Construction, Operation and Maintenance of Infrastructure Projects By the Private Sector, and for Other Purposes\"","orig":"An Act Amending Certain Sections of Republic Act No. 6957, Entitled \"An Act Authorizing the Financing, Construction, Operation and Maintenance of Infrastructure Projects By the Private Sector, and for Other Purposes\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7718","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 18 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7718_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6199-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 1 of Republic Act No. 6957 is hereby amended to read as follows:\n\"Section 1. Declaration of Policy . — It is the declared policy of the State to recognize the indispensable role of the private sector as the main engine for national growth and development and provide the most appropriate incentives to mobilize private resources for the purpose of financing the construction, operation and maintenance of infrastructure and development projects normally financed and undertaken by the government. Such incentives, aside from financial incentives as provided by law, shall include providing a climate of minimum government regulations and procedures and specific government undertakings in support of the private sector.\""}},{"id":"PH-H6199-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2 of the same Act is hereby amended to read as follows:\n\"Section 2. Definition of Terms. — The following terms used in this Act shall have the meanings stated below:\n\"(a) Private sector infrastructure or development projects — The general description of infrastructure or development projects normally financed and operated by the public sector but which will now be wholly or partly implemented by the private sector, including but not limited to, power plants, highways, ports, airports, canals, dams, hydropower projects, water supply, irrigation, telecommunications, railroads and railways, transport systems, land reclamation projects, industrial estates or townships, housing, government buildings, tourism projects, markets, slaughterhouses, warehouses, solid waste management, information technology networks and database infrastructure, education and health facilities, sewerage, drainage, dredging, and other infrastructure and development projects as may be authorized by the appropriate agency pursuant to this Act. Such projects shall be undertaken through contractual arrangements as defined hereunder and such other variations as may be approved by the President of the Philippines.\n\"For the construction stage of these infrastructure projects, the project proponent may obtain financing from foreign and/or domestic sources and/or engage the services of a foreign and/or Filipino contractor: Provided, That, in case an infrastructure or a development facility's operation requires a public utility franchise, the facility operator must be Filipino or if a corporation, it must be duly registered with the Securities and Exchange Commission and owned up to at least sixty percent (60%) by Filipinos: Provided, further, That in the case of foreign contractors, Filipino labor shall be employed or hired in the different phases of the construction where Filipino skills are available: Provided, finally, That projects which would have difficulty in sourcing funds may be financed partly from direct government appropriations and/or from Official Development Assistance (ODA) of foreign governments or institutions not exceeding fifty percent (50%) of the project cost, and the balance to be provided by the project proponent.\n\"(b) Build-operate-and-transfer — A contractual arrangement whereby the project proponent undertakes the construction, including financing, of a given infrastructure facility, and the operation and maintenance thereof. The project proponent operates the facility over a fixed term during which it is allowed to charge facility users appropriate tolls, fees, rentals, and charges not exceeding those proposed in its bid or as negotiated and incorporated in the contract to enable the project proponent to recover its investment, and operating and maintenance expenses in the project. The project proponent transfers the facility to the government agency or local government unit concerned at the end of the fixed term which shall not exceed fifty (50) years: Provided, That in case of an infrastructure or development facility whose operation requires a public utility franchise, the proponent must be Filipino or, if a corporation, must be duly registered with the Securities and Exchange Commission and owned up to at least sixty percent (60%) by Filipinos.\n\"The build-operate-and-transfer shall include a supply-and-operate situation which is a contractual arrangement whereby the supplier of equipment and machinery for a given infrastructure facility, if the interest of the Government so requires, operates the facility providing in the process technology transfer and training to Filipino nationals.\n\"(c) Build-and-transfer — A contractual arrangement whereby the project proponent undertakes the financing and construction of a given infrastructure or development facility and after its completion turns it over to the government agency or local government unit concerned, which shall pay the proponent on an agreed schedule its total investments expended on the project, plus a reasonable rate of return thereon. This arrangement may be employed in the construction of any infrastructure or development project, including critical facilities which, for security or strategic reasons, must be operated directly by the Government.\n\"(d) Build-own-and-operate — A contractual arrangement whereby a project proponent is authorized to finance, construct, own, operate and maintain an infrastructure or development facility from which the proponent is allowed to recover its total investment, operating and maintenance costs plus a reasonable return thereon by collecting tolls, fees, rentals or other charges from facility users: Provided, That all such projects, upon recommendation of the Investment Coordination Committee (ICC) of the National Economic and Development Authority (NEDA), shall be approved by the President of the Philippines. Under this project, the proponent which owns the assets of the facility may assign its operation and maintenance to a facility operator.\n\"(e) Build-lease-and-transfer — A contractual arrangement whereby a project proponent is authorized to finance and construct an infrastructure or development facility and upon its completion turns it over to the government agency or local government unit concerned on a lease arrangement for a fixed period after which ownership of the facility is automatically transferred to the government agency or local government unit concerned.\n\"(f) Build-transfer-and-operate — A contractual arrangement whereby the public sector contracts out the building of an infrastructure facility to a private entity such that the contractor builds the facility on a turn-key basis, assuming cost overrun, delay, and specified performance risks.\n\"Once the facility is commissioned satisfactorily, title is transferred to the implementing agency. The private entity however, operates the facility on behalf of the implementing agency under an agreement.\n\"(g) Contract-add-and-operate — A contractual arrangement whereby the project proponent adds to an existing infrastructure facility which it is renting from the government. It operates the expanded project over an agreed franchise period. There may, or may not be, a transfer arrangement in regard to the facility.\n\"(h) Develop-operate-and-transfer — A contractual arrangement whereby favorable conditions external to a new infrastructure project which is to be built by a private project proponent are integrated into the arrangement by giving that entity the right to develop adjoining property, and thus, enjoy some of the benefits the investment creates such as higher property or rent values.\n\"(i) Rehabilitate-operate-and-transfer — A contractual arrangement whereby an existing facility is turned over to the private sector to refurbish, operate and maintain for a franchise period, at the expiry of which the legal title to the facility is turned over to the government. The term is also used to describe the purchase of an existing facility from abroad, importing, refurbishing, erecting and consuming it within the host country.\n\"(j) Rehabilitate-own-and-operate — A contractual arrangement whereby an existing facility is turned over to the private sector to refurbish and operate with no time limitation imposed on ownership. As long as the operator is not in violation of its franchise, it can continue to operate the facility in perpetuity.\n\"(k) Project proponent — The private sector entity which shall have contractual responsibility for the project and which shall have an adequate financial base to implement said project consisting of equity and firm commitments from reputable financial institutions to provide, upon award, sufficient credit lines to cover the total estimated cost of the project.\n\"(l) Contractor — Any entity accredited under Philippine laws which may or may not be the project proponent and which shall undertake the actual construction and/or supply of equipment for the project.\n\"(m) Facility operator — A company registered with the Securities and Exchange Commission, which may or may not be the project proponent, and which is responsible for all aspects of operation and maintenance of the infrastructure or development facility, including but not limited to the collection of tolls, fees, rentals or charges from facility users: Provided, That in case the facility requires a public utility franchise, the facility operator shall be Filipino or at least sixty per centum (60%) owned by Filipinos.\n\"(n) Direct government guarantee —An agreement whereby the government or any of its agencies or local government units assume responsibility for the repayment of debt directly incurred by the project proponent in implementing the project in case of a loan default.\n\"(o) Reasonable rate of return on investments and operating and maintenance cost — The rate of return that reflects the prevailing cost of capital in the domestic and international markets: Provided, That, in case of negotiated contracts, such rate of return shall be determined by the ICC of the NEDA prior to the negotiation and/or call for proposals: Provided, further, That for negotiated contracts for public utility projects which are monopolies, the rate of return on rate base shall be determined by existing laws, which in no case shall exceed twelveper centum (12%).\n\"(p) Construction — Refers to new construction, rehabilitation, improvement, expansion, alteration and related works and activities including the necessary supply of equipment, materials, labor and services and related items.\""}},{"id":"PH-H6199-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 3 of the same Act is hereby amended to read as follows:\n\"Section 3. Private Initiative in Infrastructure. — All government infrastructure agencies, including government-owned and controlled corporations and local government units are hereby authorized to enter into contract with any duly prequalified project proponent for the financing, construction, operation and maintenance of any financially viable infrastructure or development facility through any of the projects authorized in this Act. Said agencies, when entering into such contracts, are enjoined to solicit the expertise of individuals, groups, or corporations in the private sector who have extensive experience in undertaking infrastructure or development projects.\""}},{"id":"PH-H6199-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 4 of the same Act is hereby amended to read as follows:\n\"Section 4. Priority Projects. — All concerned government agencies, including government-owned and controlled corporations and local government units, shall include in their development programs those priority projects that may be financed, constructed, operated and maintained by the private sector under the provisions of this Act. It shall be the duty of all concerned government agencies to give wide publicity to all projects eligible for financing under this Act, including publication in national and, where applicable, international newspapers of general circulation once every six (6) months and official notification of project proponents registered with them.\n\"The lists of all such national projects must be part of the development programs of the agencies concerned. The list of projects costing up to Three hundred million pesos (₱300,000,000) shall be submitted to the ICC of the NEDA for its approval and to the NEDA Board for projects costing more than Three hundred million pesos (₱300,000,000). The list of projects submitted to the ICC of the NEDA Board shall be acted upon within thirty (30) working days.\n\"The list of local projects to be implemented by the local government units concerned shall be submitted for confirmation to the municipal development council for projects costing up to twenty million pesos; those costing above twenty up to fifty million pesos to the provincial development council; those costing up to fifty million pesos to the city development council; above fifty million up to two hundred million pesos to the regional development councils; and those above two hundred million pesos to the ICC of the NEDA.\""}},{"id":"PH-H6199-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A new section is hereby added after Section 4 of the same Act and numbered as Section 4-A, to read as follows:\n\"Section 4-A. Unsolicited Proposals. — Unsolicited proposals for projects may be accepted by any government agency or local government unit on a negotiated basis: Provided, That, all the following conditions are met: (1) such projects involve a new concept or technology and/or are not part of the list of priority projects, (2) no direct government guarantee, subsidy or equity is required, and (3) the government agency or local government unit has invited by publication, for three (3) consecutive weeks, in a newspaper of general circulation, comparative or competitive proposals and no other proposal is received for a period of sixty (60) working days: Provided, further, That in the event another proponent submits a lower price proposal, the original proponent shall have the right to match that price within thirty (30) working days.\""}},{"id":"PH-H6199-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 5 of the same Act is hereby amended to read as follows:\n\"Section 5. Public Bidding of Projects. — Upon approval of the projects mentioned in Section 4 of this Act, the head of the infrastructure agency or local government unit concerned shall forthwith cause to be published, once every week for three (3) consecutive weeks, in at least two (2) newspapers of general circulation and in at least one (1) local newspaper which is circulated in the region, province, city or municipality in which the project is to be constructed, a notice inviting all prospective infrastructure or development project proponents to participate in a competitive public bidding for the projects so approved.\n\"In the case of a build-operate-and-transfer arrangement, the contract shall be awarded to the bidder who, having satisfied the minimum financial, technical, organizational and legal standards required by this Act, has submitted the lowest bid and most favorable terms for the project, based on the present value of its proposed tolls, fees, rentals and charges over a fixed term for the facility to be constructed, rehabilitated, operated and maintained according to the prescribed minimum design and performance standards, plans and specifications. For this purpose, the winning project proponent shall be automatically granted by the appropriate agency the franchise to operate and maintain the facility, including the collection of tolls, fees, rentals, and charges in accordance with Section 5 hereof.\n\"In the case of a build-and-transfer or build-lease-and-transfer arrangement, the contract shall be awarded to the lowest complying bidder based on the present value of its proposed schedule of amortization payments for the facility to be constructed according to the prescribed minimum design and performance standards, plans and specifications: Provided, however, That a Filipino contractor who submits an equally advantageous bid with exactly the same price and technical specifications as those of a foreign contractor shall be given preference.\n\"In all cases, a consortium that participates in a bid must present proof that the members of the consortium have bound themselves jointly and severally to assume responsibility for any project. The withdrawal of any member of the consortium prior to the implementation of the project could be a ground for the cancellation of the contract.\n\"The public bidding must be conducted under a two-envelope/two-stage system: the first envelope to contain the technical proposal and the second envelope to contain the financial proposal. The procedures for this system shall be outlined in the implementing rules and regulations of this Act.\n\"A copy of each contract involving a project entered into under this Act shall forthwith be submitted to Congress for its information.\""}},{"id":"PH-H6199-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A new section is hereby added after Section 5 of the same Act and numbered as Section 5-A, to read as follows:\n\"Section 5-A. Direct Negotiation of Contracts. — Direct negotiation shall be resorted to when there is only one complying bidder left as defined hereunder:\n\"(a) If, after advertisement, only one contractor applies for prequalification and it meets the prequalification requirements, after which it is required to submit a bid/proposal which is subsequently found by the agency/local government unit (LGU) to be complying.\n\"(b) If, after advertisement, more than one contractor applied for prequalification but only one meets the prequalification requirements, after which it submits bid/proposal which is found by the agency/LGU to be complying.\n\"(c) If, after prequalification of more than one contractor, only one submits a bid which is found by the agency/LGU to be complying.\n\"(d) If, after prequalification, more than one contractor submit bids but only one is found by the agency/LGU to be complying: Provided, That, any of the disqualified prospective bidder may appeal the decision of the implementing agency/LGUs prequalification bids and awards committee within fifteen (15) working days to the head of the agency, in case of national projects or to the Department of the Interior and Local Government, in case of local projects from the date the disqualification was made known to the disqualified bidder: Provided, furthermore, That the implementing agency/LGUs concerned should act on the appeal within forty-five (45) working days from receipt thereof.\""}},{"id":"PH-H6199-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 6 of the same Act is hereby amended to read as follows:\n\"Section 6. Repayment Scheme. — For the financing, construction, operation and maintenance of any infrastructure project undertaken through the build-operate-and-transfer arrangement or any of its variations pursuant to the provisions of this Act, the project proponent shall be repaid by authorizing it to charge and collect reasonable tolls, fees, and rentals for the use of the project facility not exceeding those incorporated in the contract and, where applicable, the proponent may likewise be repaid in the form of a share in the revenue of the project or other non-monetary payments, such as, but not limited to, the grant of a portion or percentage of the reclaimed land, subject to the constitutional requirements with respect to the ownership of land: Provided, That for negotiated contracts, and for projects which have been granted a natural monopoly or where the public has no access to alternative facilities, the appropriate government regulatory bodies, shall approve the tolls, fees, rentals, and charges based on a reasonable rate of return: Provided, further, That the imposition and collection of tolls, fees, rentals, and charges shall be for a fixed term as proposed in the bid and incorporated in the contract but in no case shall this term exceed fifty (50) years: Provided, furthermore, That the tolls, fees, rentals, and charges may be subject to adjustment during the life of the contract, based on a predetermined formula using official price indices and included in the instructions to bidders and in the contract: Provided, also, That all tolls, fees, rentals, and charges and adjustments thereof shall take into account the reasonableness of said rates to the end-users of private sector-built infrastructure: Provided, finally, That during the lifetime of the franchise, the project proponent shall undertake the necessary maintenance and repair of the facility in accordance with standards prescribed in the bidding documents and in the contract. In the case of a build-and-transfer arrangement, the repayment scheme is to be effected through amortization payments by the government agency or local government unit concerned to the project proponent according to the scheme proposed in the bid and incorporated in the contract.\""}},{"id":"PH-H6199-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 7 of the same Act is hereby amended to read as follows:\n\"Section 7. Contract Termination. — In the event that a project is revoked, cancelled or terminated by the government through no fault of the project proponent or by mutual agreement, the government shall compensate the said project proponent for its actual expenses incurred in the project plus a reasonable rate of return thereon not exceeding that stated in the contract as of the date of such revocation, cancellation or termination: Provided, That the interest of the government in these instances shall be duly insured with the Government Service Insurance System or any other insurance entity duly accredited by the Office of the Insurance Commissioner: Provided, finally, That the cost of the insurance coverage shall be included in the terms and conditions of the bidding referred to above.\n\"In the event that the government defaults on certain major obligations in the contract and such failure is not remediable or if remediable shall remain unremedied for an unreasonable length of time, the project proponent/contractor may, by prior notice to the concerned national government agency or local government unit specifying the turn-over date, terminate the contract. The project proponent/contractor shall be reasonably compensated by the Government for equivalent or proportionate contract cost as defined in the contract.\""}},{"id":"PH-H6199-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 8 of the same Act is hereby amended to read as follows:\n\"Section 8. Regulatory Boards. — The Toll Regulatory Board which was created by Presidential Decree No. 1112 is hereby attached to the Department of Public Works and Highways with the Secretary of Public Works and Highways as Chairman.\""}},{"id":"PH-H6199-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 9 of the same Act is hereby amended to read as follows:\n\"Section 9. Project Supervision. — Every infrastructure project undertaken under the provisions of this Act shall be in accordance with the plans, specifications, standards, and costs approved by the concerned government agency and shall be under the supervision of the said agency or local government unit in the case of local projects.\""}},{"id":"PH-H6199-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"A new section to be numbered as Section 10 is hereby added to read as follows:\n\"Section 10. Investment Incentives. — Among other incentives, projects in excess of One billion pesos (P1,000,000,000) shall be entitled to incentives as provided by the Omnibus Investments Code, upon registration with the Board of Investments.\""}},{"id":"PH-H6199-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 10 of the same Act is hereby renumbered as Section 11 to read as follows:\n\"Section 11. Implementing Rules and Regulations . — A committee composed of one (1) representative each from the Department of Public Works and Highways, the Department of Transportation and Communications, the Department of Energy, the Department of Environment and Natural Resources, the Department of Agriculture, the Department of Trade and Industry, the Department of Finance, the Department of the Interior and Local Government, the National Economic and Development Authority, the Coordinating Council of the Philippine Assistance Program, and other concerned government agencies shall, within sixty (60) days from the effectivity of this Act, formulate and prescribe, after public hearing and publication as required by law, the implementing rules and regulations including, among others, the criteria and guidelines for evaluation of bid proposals, list of financial incentives and arrangements that the government may provide for the project, in order to carry out the provisions of this Act in the most expeditious manner.\n\"The chairman of this committee shall be appointed by the President of the Philippines from its members.\n\"From time to time the committee may conduct, formulate and prescribe after due public hearing and publication, amendments to the implementing rules and regulations, consistent with the provisions of this Act.\""}},{"id":"PH-H6199-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"A new section to be numbered as Section 12 is hereby added to read as follows:\n\"Section 12. Coordination and Monitoring of Projects. — The Coordinating Council of the Philippine Assistance Program (CCPAP) shall be responsible for the coordination and monitoring of projects implemented under this Act.\n\"Regional development councils and local government units shall periodically submit to CCPAP, information on the status of said projects.\n\"At the end of every calendar year, the CCPAP shall report to the President and to Congress on the progress of all projects implemented under this Act.\""}},{"id":"PH-H6199-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Sections 11, 12, and 13 of the same Act are hereby renumbered as Sections 13,14, and 15, respectively."}},{"id":"PH-H6199-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause . — All laws or parts of any law inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6199-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Separability Clause . — If any provision of this Act is held invalid, the other provisions not affected thereby shall continue in operation."}},{"id":"PH-H6199-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation.\nApproved, May 5, 1994."}}],"pack":"ph-p88"};
  FT["PH-H6200"] = {"id":"PH-H6200","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7719_1994.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"促进自愿献血、规定充足安全血液供应、规范血库并对违规行为规定处罚的法案","en":"An Act Promoting Voluntary Blood Donation, Providing for An Adequate Supply of Safe Blood, Regulating Blood Banks, and Providing Penalties for Violation Thereof","orig":"An Act Promoting Voluntary Blood Donation, Providing for An Adequate Supply of Safe Blood, Regulating Blood Banks, and Providing Penalties for Violation Thereof"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 7719","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7719_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6200-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . — This Act shall be known as the \"National Blood Services Act of 1994.\""}},{"id":"PH-H6200-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . — In order to promote public health, it is hereby declared the policy of the State:\n(a) to promote and encourage voluntary blood donation by the citizenry and to instill public consciousness of the principle that blood donation is a humanitarian act;\n(b) to lay down the legal principle that the provision of blood for transfusion is a professional medical service and not a sale of a commodity;\n(c) to provide for adequate, safe, affordable and equitable distribution of supply of blood and blood products;\n(d) to inform the public of the need for voluntary blood donation to curb the hazards caused by the commercial sale of blood;\n(e) to teach the benefits and rationale of voluntary blood donation in the existing health subjects of the formal education system in all public and private schools, in the elementary, high school and college levels as well as the non-formal education system; 342\n(f) to mobilize all sectors of the community to participate in mechanisms for voluntary and non-profit collection of blood;\n(g) to mandate the Department of Health to establish and organize a National Blood Transfusion Service Network in order to rationalize and improve the provision of adequate and safe supply of blood;\n(h) to provide for adequate assistance to institutions promoting voluntary blood donation and providing non-profit blood services, either through a system of reimbursement for costs from patients who can afford to pay, or donations from governmental and non-governmental entities;\n(i) to require all blood collection units and blood banks/ centers to operate on a non-profit basis;\n(j) to establish scientific and professional standards for the operation of blood collection units and blood banks/centers in the Philippines;\n(k) to regulate and ensure the safety of all activities related to the collection, storage and banking of blood; and\n(l) to require upgrading of blood banks/centers to include preventive services and education to control spread of blood transfusion transmissible diseases."}},{"id":"PH-H6200-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. — For purposes of this Act, the following terms shall mean:\n(a) Blood/blood product — refers to human blood, processed or unprocessed and includes blood components, its products and derivatives;\n(b) Blood bank/center — a laboratory or institution with the capability to recruit and screen blood donors, collect, process, store, transport and issue blood for transfusion and provide information and/or education on blood transfusion transmissible diseases;\n(c) Commercial blood bank — a blood bank that exists for profit;\n(d) Hospital-based blood bank — a blood bank which is located within the premises of a hospital and which can perform compatibility testing of blood;\n(e) Blood collection unit — an institution or facility duly authorized by the Department of Health to recruit and screen donors and collect blood;\n(f) Voluntary blood donor — one who donates blood on one's own volition or initiative and without monetary compensation;\n(g) Department — the Department of Health;\n(h) Blood transfusion transmissible diseases - diseases which may be transmitted as a result of blood transfusion, including AIDS, Hepatitis-B, Malaria and Syphilis;\n(i) Secretary of Health — the Secretary of Health or any other person to whom the Secretary delegates the responsibility of carrying out the provisions of this Act; and\n(j) Walking Blood Donor — an individual included in the list of qualified voluntary blood donors referred to in Section 4, paragraph (e), who is ready to donate blood when needed in his/ her community."}},{"id":"PH-H6200-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Promotion of Voluntary Blood Donation. — In order to ensure adequate supply of human blood, voluntary blood donation shall be promoted through the following:\n(a) Public Education. — Through an organized and sustained nationwide public education campaign by the Department, the Philippine National Red Cross (PNRC) and the Philippine Blood Coordinating Council (PBCC), as the lead agencies, other government agencies, local government units (particularly the barangays), non-governmental organizations, all medical organizations, all public and private hospitals, all health and health-related institutions, print and broadcast media as well as other sectors. The Department is hereby authorized to set aside funds and generate financial support for all sectors involved in the collection and processing of blood from voluntary blood donors through a system of reimbursement for costs for patients who can afford to pay or from donations from government and private institutions. Voluntary donors shall likewise be provided nonmonetary incentives as may be determined by the Department.\n(b) Promotion in Schools. — The benefits and rationale of voluntary blood donation shall be included and given emphasis in health subjects of schools, both public and private, at the elementary, high school and college levels. The Department of Education, Culture and Sports shall also require such inclusion in its non-formal education curricula.\n(c) Professional Education. — The Department, the PBCC, the Philippine Society of Hematology and Blood Transfusion (PSHBT), the Philippine Society of Pathologists (PSP), the Philippine Medical Association (PMA), the Philippine Association of Medical Technologists (PAMET) and the Philippine Nursing Association (PNA) are encouraged to conduct for their respective members and as part of the continuing medical education, trainings on the rational use of blood and blood products including the merits of voluntary blood donation.\n(d) Establishment of Blood Services Network. — Blood centers shall be strategically established in every province and city nationwide within the framework of a National Blood Transfusion Service Network spearheaded by the Department, in coordination with the PNRC. The collection of blood in various areas in the community, such as schools, business enterprises, barangays, and military camps shall be promoted. The Secretary shall set the standards for the scientific and professional establishment and operation of blood banks/centers and collection units. The Department shall provide training programs and technical assistance to enable communities, schools, industrial and business sites, barangays, military camps and local government units to implement their own voluntary blood donation programs.\n(e) Walking Blood Donors. — In areas where there may be inadequate blood banking facilities, the walking blood donor concept shall be encouraged and all government hospitals, ruralhealth units, health centers and barangays in these areas shall be required to keep at all times a list of qualified voluntary blood donors with their specified blood typing."}},{"id":"PH-H6200-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"National Voluntary Blood Services Program. — The Department, in cooperation with the PNRC and PBCC and other government agencies and non-governmental organizations shall plan and implement a National Voluntary Blood Services Program (NVBSP) to meet in an evolutionary manner, the needs for blood transfusion in all regions of the country. Funds for this purpose shall be provided by the Government through the budgetary allocation of the Department, by the Philippine Charity Sweepstakes Office (PCSO) with an initial amount of at least Twenty-five million pesos (₱25,000,000), by the Philippine Amusement and Gaming Corporation (PAGCOR) with an initial amount of at least Twenty-five million pesos (₱25,000,000), by the trust liability account of the Duty Free Shop (Duty Free Philippines) with an initial amount of at least Twenty million pesos (₱20,000,000) and through contributions of other agencies such as civic organizations."}},{"id":"PH-H6200-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Upgrading of Services and Facilities. — All blood banks/centers shall provide preventive health services such as education and counselling on blood transfusion transmissible diseases. All government hospitals, including those that have been devolved, shall be required to establish voluntary blood donation programs and all private hospitals shall be encouraged to establish voluntary blood donation programs.\nThe Department, in consultation with the PSHBT and the PSP, shall also establish guidelines for the rational use of blood and blood products."}},{"id":"PH-H6200-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Phase-out of Commercial Blood Banks. — All commercial blood banks shall be phased-out over a period of two (2) years after the effectivity of this Act, extendable to a maximum period of two (2) years by the Secretary."}},{"id":"PH-H6200-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Non-Profit Operation. — All blood banks/centers shall operate on a non-profit basis: Provided, That they may collect service fees not greater than the maximum prescribed by the Department which shall be limited to the necessary expenses entailed in collecting and processing of blood. Blood shall be collected from healthy voluntary donors only."}},{"id":"PH-H6200-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Regulation of Blood Services. — It shall be unlawful for any person to establish and operate a blood bank/center unless it is registered and issued a license to operate by the Department: Provided, That in case of emergencies, blood collection and transfusion under the responsibility of the attending physician shall be allowed in hospitals without such license under certain conditions prescribed by the Department. No license shall be granted or renewed by the Department for the establishment and operation of a blood bank/center unless it complies with the standards prescribed by the Department. Such blood bank/center shall be under the management of a licensed and qualified physician duly authorized by the Department."}},{"id":"PH-H6200-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Importation of Blood Bank Equipment, Blood Bags and Reagents. — Upon the effectivity of this Act, equipment, blood bags and reagents used for the screening and testing of donors, collection and processing and storage of blood shall be imported tax-and duty-free by the PNRC, blood banks and hospitals participating actively in the National Voluntary Blood Services Program. This provision shall be implemented by the rules and regulations to be promulgated by the Department in consultation and coordination with the Department of Finance."}},{"id":"PH-H6200-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Rules and Regulations. — The implementation of the provisions of this Act shall be in accordance with the rules and regulations to be promulgated by the Secretary, within sixty (60) days from the approval hereof. The existing Revised Rules and Regulations Governing the Collection, Processing and Provision of Human Blood and the Establishment and Operation of Blood Banks shall remain in force unless amended or revised by the Secretary. The rules and regulations shall prescribe from time to time the maximum ceiling for fees for the provision of blood, including its collection, processing and storage, professional services and a reasonable allowance for spoilage."}},{"id":"PH-H6200-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Penalties. — Upon complaint of any person and after due notice and hearing, any blood bank/center which shall collect charges and fees greater than the maximum prescribed by the Department shall have its license suspended or revoked by the Secretary.\nAny person or persons who shall be responsible for the above violation shall suffer the penalty of imprisonment of not less than one (1) month nor more than six (6) months, or a fine of not less than Five thousand pesos (P5,000) nor more than Fifty thousand pesos (₱50,000), or both at the discretion of the competent court.\nAny person who shall establish and operate a blood bank without securing any license to operate from the Department or who fails to comply with the standards prescribed by the Department referred to in Section 9 hereof shall suffer the penalty of imprisonment of not less than twelve (12) years and one (1) day nor more than twenty (20) years or a fine of not less than Fifty thousand pesos (₱50,000) nor more than Five hundred thousand pesos (₱500,000), or both at the discretion of the competent court.\nThe Secretary, after due notice and hearing, may impose administrative sanctions such as, but not limited to fines, suspension, or revocation of license to operate a blood bank/center and to recommend the suspension or revocation of the license to practice the profession when applicable.\nThe head of the blood bank and the necessary trained personnel under the head's direct supervision found responsible for dispensing, transfusing and failing to dispose, within fortyeight (48) hours, blood which have been proven contaminated with blood transfusion transmissible diseases shall be imprisoned for ten (10) years. This is without prejudice to the filing of criminal charges under the Revised Penal Code."}},{"id":"PH-H6200-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. — If any provision of this Act is declared invalid, the other provisions hereof not affected thereby shall remain in force and effect."}},{"id":"PH-H6200-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause. — This Act shall supersede Republic Act No. 1517 entitled \"Blood Bank Act.\" The provisions of any law, executive order, presidential decree or other issuances inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6200-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause . — This Act shall take effect after fifteen (15) days following its publication in the Official Gazette or in two (2) national newspapers of general circulation.\nApproved, May 5, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Promoting Voluntary Blood Donation, Providing for An Adequate Supply of Safe Blood, Regulating Blood Banks, and Providing Penalties for Violation Thereof","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6201"] = {"id":"PH-H6201","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7720_1994.html","fetchedAt":"2026-10-06","articleCount":54,"structureMode":"ARTICLE","title":{"zh":"将Santiago镇改制为市","en":"An Act Converting the Municipality of Santiago Into An Independent Component City to Be Known as the City of Santiago","orig":"An Act Converting the Municipality of Santiago Into An Independent Component City to Be Known as the City of Santiago"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7720","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-05","completenessNote":"全文，共 54 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7720_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6201-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . — This Act shall be known as the Charter of the City of Santiago."}},{"id":"PH-H6201-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The City of Santiago. — The Municipality of Santiago shall be converted into an independent component city to be known as the City of Santiago, hereinafter referred to as the City, which shall comprise of the present territory of the Municipality of Santiago, Isabela. The territorial jurisdiction of the City shall be within the present metes and bounds of the Municipality of Santiago."}},{"id":"PH-H6201-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Corporate Powers of the City. — The City constitutes a political body corporate and as such is endowed with the attributes of perpetual succession and possessed of the powers which pertain to a municipal corporation to be exercised in conformity with the provisions of this Charter. The City shall have the following corporate powers:\n(1) To have a continuous succession in its corporate name;\n(2) To sue and be sued;\n(3) To have and use a corporate seal;\n(4) To acquire and convey real or personal property;\n(5) To enter into contracts; and\n(6) To exercise such other powers as are granted to corporations, subject to the limitations provided in this Act and other laws."}},{"id":"PH-H6201-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"General Powers of the City. — The City shall have a common seal and may alter the same at pleasure. It shall exercise the powers to levy taxes and close roads, streets, alleys, parks or squares. It may take, purchase, receive, hold, lease, convey and dispose of real and personal property for the general interest of the City, condemn private property for public use, contract and be contracted with, sue and be sued, prosecute and defend to final judgment and execution suits wherein said City is a party and exercise all the powers as are granted to corporations and/or hereinafter conferred."}},{"id":"PH-H6201-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Liability of Damages. — The City and its officials shall not be exempt from liability for death or injury to persons or damage to property."}},{"id":"PH-H6201-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Jurisdiction of the City. — The jurisdiction of the City of Santiago, for police purposes only, shall be coextensive with its territorial jurisdiction and for the purpose of protecting and insuring the purity of the water supply of the City, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The city court of the City shall have concurrent jurisdiction with the city or municipal courts of adjoining municipalities or cities, to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters. The court first taking cognizance of such an offense shall have jurisdiction to try said cases to the exclusion of others. The police force of the several municipalities and cities concerned shall have concurrent jurisdiction with the police force of the City for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued within said zone, area or spaces shall be granted by the proper authorities of the city or municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said city or municipality.\nArticle II. CITY OFFICIALS IN GENERAL"}},{"id":"PH-H6201-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Officials of the City of Santiago. — There shall be in the City of Santiago a city mayor, a vice-mayor, sangguniang panlungsod members, a secretary to the sangguniang panlungsod, a city treasurer and an assistant city treasurer, a city assessor and an assistant city assessor, a city accountant, a city budget officer, a city planning and development coordinator, a city engineer, a city health officer, a city civil registrar, a city administrator, a city legal officer, a city veterinarian, a city social welfare and development officer, and a city general services officer.\n(b) In addition thereto, the city mayor may appoint a city architect, a city information officer, a city population officer, a city environment and natural resources officer, and a city cooperatives officer.\n(c) The City of Santiago shall establish a city fire station to be headed by a city fire marshal and a city jail to be headed by a city jail warden.\n(d) The City of Santiago may:\n(1) Maintain existing offices not mentioned in subsections (a) and (b ) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the City; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy.\n(e) Unless otherwise provided herein, all appointive city officials of the City shall be appointed by the city mayor with the concurrence of the majority of all the sangguniang panlungsod members, subject to civil service law, rules and regulations. The sangguniang panlungsod shall act on the appointments within fifteen (15) days from the date of is submission, otherwise the same shall be deemed confirmed.\nArticle III. THE CITY MAYOR AND VICE-MAYOR"}},{"id":"PH-H6201-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The City Mayor. — (a) The city mayor shall be the chief executive of the City. He shall be elected at large by the qualified voters of the City.\nNo person shall be eligible for the position of city mayor unless at the time of the election:\n(1) He is at least twenty-three (23) years of age;\n(2) An actual resident of the City for at least one (1) year prior to his election; and\n(3) A qualified voter therein.\nHe shall hold office for three (3) years, unless sooner removed, and shall receive a minimum monthly compensation corresponding to salary grade thirty (30) as prescribed under Republic Act No. 6758 and the implementing guidelines issued pursuant thereto.\n(b) The city mayor, as the chief executive of the city government, shall exercise such powers and perform such duties and functions as provided herein:\n(1) Exercise those powers expressly granted to him by law, those necessarily implied therefrom, as well as powers necessary, appropriate, or incidental for the efficient and effective governance of the City and those which are essential to the promotion of general welfare:\n(a) Determine the guidelines of city policies and be responsible to the sangguniang panlungsod for the program of government;\n(b) Direct the formulation of the city development plan with the assistance of the city development council and, upon approval thereof by the sangguniang panlungsod, implement the same;\n(c) Present the program of government and propose policies and projects for the consideration of the sangguniang panlungsod every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the city government may require;\n(d) Initiate and propose legislative measures to the sangguniang panlungsod and, as often as may be deemed necessary, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(e) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of city funds and whose appointments are not otherwise provided for in this Act as well as those he may be authorized by law to appoint;\n(f) Represent the City in all its business transactions and sign in its behalf all bonds, contracts, and obligations, and such other documents upon authority of the sangguniang panlungsod or pursuant to existing laws or ordinances;\n(g) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(h) Determine the time, manner and place of payment of salaries or wages of the officials and employees of the City, in accordance with law or ordinance;\n(i) Allocate and assign office space to the City and other officials and employees who, by law or ordinance, are entitled to such space in the city hall and other buildings owned or leased by the city government;\n(j) Ensure that all executive officials and employees of the City faithfully discharge their duties and functions as provided by law and this Act and cause to be instituted administrative or judicial proceedings against any official or employee of the City who may have committed an offense in the performance of his official duties;\n(k) Examine the books, records and other documents of all offices, officials, agents or employees of the City and, in aid of his executive powers and authority, require all national officials and employees stationed in or assigned to the City to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(l) Furnish copies of executive orders issued by him to the respective council chairman within seventy-two (72) hours after their issuance;\n(m) Visit component barangays of the City at least once every six (6) months to deepen his understanding of problems and conditions, listen and give appropriate counsel to local officials and inhabitants of general laws and ordinances which especially concern them and otherwise conduct visits and inspections to ensure that the governance of the City will improve the quality of life of the inhabitants;\n(n) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of their leave credits in accordance with law;\n(o) Authorize official trips of city officials and employees outside of the City for a period not exceeding thirty (30) days;\n(p) Call upon any national official or employee stationed in or assigned to the City to advise him on matters affecting the City and to make recommendations thereon; coordinate with said officials or employees in the formulation and implementation of plans, programs and projects; and, when appropriate, initiate any administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the City;\n(q) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of city officials and employees who are injured while in the performance of their official duties and functions, subject to the availability of funds;\n(r) Solemnize marriages, any provision of law to the contrary notwithstanding;\n(s) Conduct an annual palarong panlungsod, which shall feature traditional sports and disciplines included in national and international games, in coordination with the Department of Education, Culture and Sports; and\n(t) Submit to the respective metropolitan authority council chairman and to the Office of the President the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the City and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the City;\n(2) Enforce all laws and ordinances relative to the governance of the City and in the exercise of its appropriate corporate powers as well as implement all approved policies, programs, projects, services, and activities of the City;\n(a) Ensure that the acts of the City's component barangays are within the scope of their prescribed powers, duties and functions;\n(b) Call conventions, conferences, seminars, or meetings of elective and appointive officials of the City, including national officials and employees stationed in or assigned to the City, at such time and place and on such subject as he may deem important for the promotion of the general welfare of the local government unit and its inhabitants;\n(c) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(d) Be entitled to carry the necessary firearm within his territorial jurisdiction;\n(e) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the City and upon its approval, implement the same as such exercise general and operational control and supervision over the local police forces in the City, in accordance with Republic Act No. 6975;\n(f) Call upon the appropriate law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition, or to apprehend violators of the law when public interest so requires and the city police forces are inadequate to cope with the situation or the violators;\n(3) Initiate and maximize the generation of resources and revenues and apply the same in the implementation of development plans, program objectives and priorities, particularly those resources and revenues programmed for agro-industrial development and countryside growth and progress;\n(a) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process in accordance with the provisions of the Local Government Code;\n(b) Prepare and submit to the sanggunian, for approval, the executive and supplemental budgets of the City for the ensuing calendar year in the manner provided for under the Local Government Code;\n(c) Ensure that all taxes and other revenues of the City are collected and that city funds are applied to the payment of expenses and settlement of obligations of the City in accordance with law or ordinance;\n(d) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued pursuant to law or ordinance;\n(e) Issue permits without need of approval from any national agency for the holding of activities for any charitable or welfare purpose, excluding prohibited games of chance or shows contrary to law, public policy, and public morals;\n(f) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permit, subject to such fines and penalties as may be imposed by law or ordinance, or to make necessary changes in the construction of the same when said construction violates any law or ordinance, or to order the demolition or removal of said house, building or structure within the period prescribed by law or ordinance;\n(g) Adopt adequate measures to safeguard and conserve land, mineral, forest, and other resources of the City;\n(h) Provide efficient and effective property and supply management in the City; and protect the funds, credits, rights and other properties of the City; and\n(i) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property; and cause the City to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n(4) Ensure the delivery of basic services and the provision of adequate facilities and, in additional thereto:\n(a) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the City; and\n(b) Coordinate the implementation of technical services, including public works and infrastructure programs, rendered by national offices.\n(5) Perform such other duties and functions and exercise such other powers, as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The City Vice-Mayor. — (a) There shall be a vice-mayor who shall be elected in the same manner as the city mayor and shall at the time of his election possess the same qualifications as the city mayor. He shall hold office for three (3) years, unless sooner removed and shall receive a monthly compensation corresponding to salary grade twenty-eight (28) as prescribed under Republic Act No. 6578 and the implementing guidelines issued pursuant thereto.\n(b) The vice-mayor shall:\n(1) Act as presiding officer of the sangguniang panlungsod and sign all warrants drawn on the city treasury for all expenditures appropriated for the operation of the sangguniang panlungsod;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang panlungsod, except those whose manner of appointment is specifically provided for under existing laws;\n(3) Assume the office of the city mayor for the unexpired term of the latter in the event of permanent vacancy;\n(4) Exercise the powers and perform the duties and functions of the city mayor in cases of temporary vacancy; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance.\nARTICLE IV. THE SANGGUNIANG PANLUNGSOD"}},{"id":"PH-H6201-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Sangguniang Panlungsod. — (a) The sangguniang panlungsod, the legislative body of the City, shall composed of the city vice-mayor as presiding officer, the regular sanggunian members, the president of the city chapter of the liga ng mga barangay, the president of the panlungsod na pederasyon ng mga sangguniang kabataan and the sectoral representatives, as members.\n(b) In addition thereto, there shall be three (3) sectoral representatives: one (1) from the women; and as shall be determined by the sangguniang panlungsod within ninety (90) days prior to the holding of the local elections, one (1) from the agricultural or industrial workers and one (1) from the other sectors, including the urban poor, indigenous cultural communities and disabled persons.\n(c) The regular members of the sangguniang panlungsod and the sectoral representatives shall be elected in the manner as may be provided by law. The elective members of the sangguniang panlungsod shall possess the same qualifications as that of the city mayor and vice-mayor.\n(d) They shall receive such compensation, emoluments, and allowances as may be determined by law.\n(e) The sangguniang panlungsod shall:\n(1) Approve ordinances and pass resolutions necessary for an efficient and effective city government and relative hereto shall:\n(a) Review all ordinances approved by the sangguniang barangay and executive orders issued by the punong barangay to determine whether these are within the scope of the prescribed powers of the sangguniang barangay and the punong barangay;\n(b) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(c) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000) or an imprisonment for a period not exceeding one (1) year, or both at the discretion of the court, for the violation of a city ordinance;\n(d) Adopt measures to protect the inhabitants of the City from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters or calamities and in their return to productive livelihood following said events;\n(e) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution and exhibition of obscene or pornographic materials or publications, and such other activities inimical to the welfare and morals of the inhabitants of the City;\n(f) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging and smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash-and-burn farming, and such other activities which result in pollution, acceleration of eutrophication of rivers and lakes or of ecological imbalance;\n(g) Subject to the provisions of the Local Government Code and pertinent laws, determine the powers and duties of officials and employees of the City;\nh. Determine the positions and the salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from city funds and provide for expenditure necessary for the proper conduct of programs, projects, services and activities of the city government;\n(i) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity at the rate authorized by law;\n(j) Provide a mechanism and the appropriate funds therefore, to ensure the safety and protection of all city government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the city government;\n(k) When the finances of the city government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed in or assigned to the City;\n(l) Provide legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(m) Provide for group insurance or additional insurance coverages for all barangay officials, including members of barangay tanod brigades and other service units, with public or private insurance companies, when the finances of the city government allow such coverage;\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the City, with particular attention to agro-industrial development and city-wide growth and progress;\n(a) Approve the annual and supplemental budgets of the city government and appropriate funds for specific programs, projects, services and activities of the City, or for other purposes not contrary to law in order to promote the general welfare of the City and its inhabitants;\n(b) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all members of the sangguniang panlungsod, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or reliefs;\n(c) Subject to the provisions of Book II of the Local Government Code and upon the majority vote of all members of the sangguniang panlungsod, authorize the city mayor to negotiate and contract loans and other forms of indebtedness;\n(d) Subject to the provisions of Book II of the Local Government Code and applicable laws and upon the majority vote of all the members of the sangguniang panlungsod, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(e) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the City; and upon the majority vote of all the members of the sangguniang panlungsod, authorize the city mayor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(f) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the City;\n(g) Adopt a comprehensive land use for the City;\n(h) Reclassify land within the jurisdiction of the City, subject to the pertinent provisions of the Local Government Code:\n(i) Enact integrated zoning ordinances in consonance with the approved comprehensive land use plan, subject to existing laws, rules and regulations; establish fire limits or zones, particularly in populous centers, and regulate the construction, repair or modification of buildings within said fire limits or zones in accordance with the provisions of the Fire Code\n(j) Subject to national law, process and approve subdivision plans for residential, commercial, or industrial purposes and other development purposes, and to collect processing fees and other charges, the proceeds of which shall accrue entirely to the City: Provided, however, That where approval of a national agency or office is required, such shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval thereof;\n(k) Subject to the provisions of Book II of the Local Government Code, grant the exclusive privilege of constructing fish corrals or fish pens, prawn fry or kawag-kawag, or fry of any species or fish within the city waters;\n(l) With the concurrence of at least two-thirds (2/3) of all members of the sangguniang panlungsod, grant tax exemptions, incentives or reliefs to entities, engaged in community growth-inducing industries, subject to the provisions of the Local Government Code;\n(m) Grant loans or provide grants to other local government units or to national, provincial, and city charitable, benevolent or educational institutions: Provided, That said institutions are operated and maintained within the City;\n(n) Regulate the numbering of residential, commercial and other buildings; and\n(o) Regulate inspection, weighing and measuring of articles of commerce;\n(3) Subject to the provisions of the Local Government Code of 1991, enact ordinances granting franchises and authorizing the issuance of permits or licenses, upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the City, and pursuant to this legislative authority, shall:\n(a) Fix and impose reasonable fees and charges for all services rendered by the city government to private persons or entities;\n(b) Regulate or fix license fees for any business or practice of profession within the City and the conditions under which the license for said business or practice of profession may be revoked and enact ordinances levying taxes thereon;\n(c) Provide for and set the terms and conditions under which public utilities owned by the City shall be operated by the city government, and prescribe the conditions under which the same may be leased to private persons or entities, preferably cooperatives;\n(d) Regulate the display of and fix the license fees for signs, signboards, or billboards at place or places where the profession or business advertised thereby is, in whole or in part, conducted:\n(e) Any law to the contrary notwithstanding, authorize and license the establishment, operation and maintenance of cockpits and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights should not be prejudiced;\n(f) Subject to the guidelines prescribed by the Department of Transportation and Communications, regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the City; and\n(g) Upon approval by a majority vote of all the members of the sangguniang panlungsod, grant a franchise to any person, partnership, corporation, or cooperatives to do business within the City, establish, construct, operate and maintain ferries, markets or slaughterhouses; or undertake such other activities within the City as may be allowed by existing laws: Provided, That cooperatives shall be given preference in the grant of such franchise;\n(4) Regulate activities relative to the use of land, buildings and structures within the City in order to promote the general welfare and for said purpose shall:\n(a) Declare, prevent or abate any nuisance;\n(b) Require that buildings and the premises thereof and any land within the City be kept and maintained in a sanitary condition; impose penalties for any violation thereof; or upon failure to comply with said requirement, have the work done at the expense of the owner, administrator or tenant concerned; or require the filling up of any land or premises to a grade necessary for proper sanitation;\n(c) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(d) Regulate the establishment, operation and maintenance of cafes, restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses, and other similar establishments, including tourist guides and transports;\n(e) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(f) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the City;\n(g) Regulate the establishment, operation, and maintenance of any entertainment or amusement facilities, including the theatrical performances, circuses, billiard pools, public dancing schools, public dance halls, sauna baths, massage parlors, and other places for entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community; and\n(h) Regulate the establishment, operation and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations.\n(5) Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided for under the Local Government Code, and in addition to said services and facilities, shall:\n(a) Provide for the establishment, maintenance, protection and conservation of communal forests and watersheds, tree parks, green belts, and other similar forest development projects;\n(b) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof by the city government and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(c) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products and other foodstuffs for public consumption;\n(d) Regulate the use of streets, avenues, alleys, sidewalks, bridges, parks and other public places and approved the construction, improvement, repair and maintenance of the same; establish bus and vehicle stops and terminals or regulate the use of the same privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; and provide for the lighting, cleaning and sprinkling of streets and public places;\n(e) Regulate traffic on all streets and bridges; prohibit encroachments or obstacles thereon and, when necessary in the interest of public welfare, authorize the removal of encroachments and illegal constructions in public places;\n(f) Subject to existing laws, establish and provide for the maintenance, repair and operation of an efficient waterworks system to supply water for the inhabitants and to purify the source of the water supply; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and quantity of the water supply of the City and, for this purpose, extend the coverage of appropriate ordinances over all territory within the drainage area of said water supply and within one hundred meters (100 m.) of the reservoir, conduit, canal, aqueduct, pumping station, or watershed used in connection with the water service; and regulate the consumption, use or wastage of water and fix and collect charges thereof;\n(g) Regulate the drilling and excavation of the ground for the laying of water, gas, sewer, and other pipes, and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalks, curbs, and gutters; adopt measures to ensure public safety against open canals, manholes, live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(h) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric, telegraph and telephone wires, conduits, meters, and other apparatus; and provide for the correction, condemnation or removal of the same when found to be dangerous, defective or otherwise hazardous to the welfare of the inhabitants;\n(i) Subject to the availability of funds and to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions with the approval of the Department of Education, Culture and Sports and subject to existing laws on tuition fees and other school charges in educational institutions supported by the city government;\n(j) Establish a scholarship fund for poor but deserving students in schools located within its jurisdiction or for students residing within the City;\n(k) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases;\n(l) Provide for an efficient and effective system of solid wastes and garbage collection and prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(m) Provide for the care of disabled persons, paupers, the aged, the sick, persons of unsound mind, abandoned minors, juvenile delinquents, drug dependents, abused children and youth below eighteen (18) years of age, and, subject to availability of funds, establish and provide for the operation of centers and facilities for said needy and disadvantaged persons;\n(n) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program, and appropriate funds for the subsistence of detainees and convicted prisoners in the City;\n(o) Establish a city council whose purpose is the promotion of culture and the arts, coordinate with government agencies and nongovernmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(p) Establish a city council for the elderly which shall formulate policies and adopt measures beneficial to the elderly and to the community; provide incentives for nongovernmental agencies and entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly; and\n(6) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance.\nARTICLE V. PROCESS OF LEGISLATION"}},{"id":"PH-H6201-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Internal Rules of Procedure. — (a) On the first regular session following the election of its members and within ninety (90) days after thereafter, the sangguniang panlungsod shall adopt or update its existing rules of procedure.\n(b) The rules of procedure shall provide for the following:\n(1) The organization of the sanggunian and the election of its officers as well as the creation of standing committees which shall include, but shall not be limited to, the committees on appropriations, women and family, human rights, youth and sports development, environmental protection, and cooperatives; the general jurisdiction of each committee; and the election of chairman and members of each committee;\n(2) The order and calendar of business for each session;\n(3) The legislative process;\n(4) The parliamentary procedures which include the conduct of members during sessions;\n(5) The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions, for which they may be censured, reprimanded, or excluded from the session, suspended for not more than sixty (60) days, or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) vote of all the sanggunian members: Provided, further, That a member convicted by final judgment to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the sanggunian; and\n(6) Such other rules as the sanggunian may adopt."}},{"id":"PH-H6201-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Full Disclosure of Financial and Business Interest of Sangguniang Panlungsod Members. —\n(a) Every sangguniang panlungsod member shall, upon assumption to office, make a full disclosure of his business and financial interest. He shall also disclose any business, financial, or professional relationship or any relation by affinity or consanguinity within the fourth civil degree, which he may have with any person, firm or entity affected by any ordinance or resolution under consideration by the sanggunian of which he is a member, which relationship may result in conflict of interest. Such relationship shall include:\n(1) Ownership of stock or capital or investment in the entity or firm to which the ordinance or resolution may apply; and\n(2) Contracts or agreements with any person or entity which the ordinance or resolution under consideration may affect.\nIn the absence of a specific constitutional or statutory provision applicable to this situation, \"conflict of interest\" refers in general to one where it may be reasonably deduced that a member of a sanggunian may not act in the public interest due to some private, pecuniary or other personal considerations that may tend to affect his judgment to the prejudice of the service or the public.\n(b) The disclosure required under this Act shall be made in writing and submitted to the secretary of the sanggunian or the secretary of the committee of which he is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n(1) Disclosure shall be made before the member participates in the deliberations on the ordinance or resolution under consideration: Provided, That if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n(2) Disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection, or professional relationship described herein."}},{"id":"PH-H6201-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sessions. — a. On the first day of the session immediately following the election of its members, the sangguniang panlungsod shall, by resolution, fix the day, time and place of its regular sessions. The minimum number of regular sessions shall be once a week for the sangguniang panlungsod, and twice a month for the sangguniang barangay.\n(b)When public interest so demands, special sessions may be called by the city mayor or by a majority of the members of the sanggunian.\n(c) All sanggunian sessions shall be open to the public unless a closed-door session is ordered by the affirmative vote of a majority of the members present, there being a quorum, in the public interest or for reasons of security, decency or morality. No two (2) sessions, regular or special, may be held in a single day.\n(d) In the case of special sessions of the sanggunian, a written notice to the members shall be served personally at the member's usual place of residence at least twenty-four (24) hours before the special session is held.\nUnless concurred in by two-thirds (2/3) vote of the sanggunian members present, there being a quorum, no other matters may be considered at a special session except those stated in the notice.\nThe sanggunian shall keep a journal and record of its proceedings which may be published upon resolution of the sangguniang panlungsod."}},{"id":"PH-H6201-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Quorum. — (a) A majority of all the members of the sanggunian who have been elected and qualified shall constitute a quorum to transact official business. Should a question of quorum be raised during a session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the results.\n(b) Where there is no quorum, the presiding officer may declare a recess until such time as a quorum is constituted, or a majority of the members present may adjourn from day to day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the sanggunian, to be assisted by a member or members of the police force assigned to the territorial jurisdiction of the City of Santiago, to arrest the absent member and present him at the session.\n(c) If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H6201-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Approval of Ordinances. — (a) Every ordinance enacted by the sangguniang panlungsod shall be presented to the city mayor. If the city mayor approves the same, he shall affix his signature on each and every page thereof; otherwise, he shall veto it and return the same with his objections to the sanggunian, which may proceed to reconsider the same. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\n(b) The veto shall be communicated by the city mayor to the sanggunian within ten (10) days; otherwise, the ordinance shall be deemed approved as if he had signed it."}},{"id":"PH-H6201-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Veto Power of the City Mayor. — (a) The city mayor may veto any ordinance of the sangguniang panlungsod on the ground that it is ultra vires or prejudicial to the public welfare, stating his reasons therefor in writing.\n(b) The city mayor shall have the power to veto any particular item or items of an appropriations ordinance, an ordinance or resolution adopting a local development plan, any public investment program, or an ordinance directing the payment of money or creating liability. In such case, the veto shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the sangguniang panlungsod overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\n(c) The city mayor may veto an ordinance or resolution only once. The sanggunian may override the veto of the city mayor by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the city mayor."}},{"id":"PH-H6201-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Review of Barangay Ordinances by the Sangguniang Panlungsod. — a. Within ten (10) days after its enactment, the sangguniang barangay shall furnish copies of all barangay ordinances to the sangguniang panlungsod for review as to whether the ordinance is consistent with law and city ordinances.\n(b) If the sangguniang panlungsod fails to take action on barangay ordinances within thirty (30) days from receipt thereof, the same shall be deemed approved.\n(c) If the sangguniang panlungsod finds the barangay ordinances inconsistent with law or city ordinances, the sangguniang panlungsod shall, within thirty (30) days from receipt thereof, return the same with its comments and recommendations to the sangguniang barangay concerned for adjustment, amendment, or modification; in which case, the effectivity of the barangay ordinance is suspended until such time as the revision called for is effected."}},{"id":"PH-H6201-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Enforcement of Disapproved Ordinances or Resolutions. — Any attempt to enforce any ordinance or any resolution approving the local development plan and public investment program, after the disapproval thereof, shall be sufficient ground for the suspension or dismissal of the official or employee concerned."}},{"id":"PH-H6201-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity of Ordinances or Resolutions. — a. Unless otherwise stated in the ordinance or the resolution approving the local development plan and public investment program, the same shall take effect after ten (10) days from the date a copy thereof is posted in a bulletin board at the entrance of the city hall of Santiago, and in at least two (2) other conspicuous places in the City of Santiago.\n(b) The secretary to the sangguniang panlungsod shall cause the posting of an ordinance or resolution in the bulletin board at the entrance of the city hall of Santiago and in at least two (2) conspicuous places in the City of Santiago not later than five (5) days after approval thereof.\nThe text of the ordinance or resolution shall be disseminated and posted in Filipino or English and in the language or dialect understood by the majority of the people in the City and the secretary of the sangguniang panlungsod shall record such fact in a book kept for the purpose, stating the dates of approval and posting.\n(c) The main features of the ordinance or resolution duly enacted or adopted shall, in addition to being posted, be published once in a local newspaper of general circulation within the City: Provided, That in the absence thereof, the ordinance or resolution shall be published in any newspaper of general circulation: Provided, further, That the gist of all ordinances with penal sanctions shall also be published in a newspaper of general circulation.\nARTICLE VI. DISQUALIFICATION AND SUCCESSION OF ELECTIVE CITY OFFICIALS"}},{"id":"PH-H6201-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Disqualifications for Elective City Officials. — The following persons are disqualified from running for any elective position in the City:\n(a) Those sentenced by final judgment for an offense involving moral turpitude or for an offense punishable by one (1) year or more of imprisonment, within two (2) years after serving sentence;\n(b) Those removed from office as a result of an administrative case;\n(c) Those convicted by final judgment for violating the oath of allegiance to the Republic of the Philippines;\n(d) Those with dual citizenship;\n(e) Fugitives from justice in criminal or non-political cases here and abroad;\n(f) Permanent residents in a foreign country or those who have acquired the right to reside abroad and continue to avail of the same right after the effectivity of the Local Government Code; and\n(g) The insane or feeble-minded."}},{"id":"PH-H6201-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Permanent Vacancy in the Office of the City Mayor and City Vice-Mayor. — (a) If a permanent vacancy occurs in the office of the city mayor, the city vice-mayor concerned shall become the city mayor. If a permanent vacancy occurs in the office of the vice-mayor, the highest ranking sangguniang panlungsod member or, in case of his permanent incapacity, the second highest ranking sangguniang panlungsod member, shall become the city mayor or city vice-mayor, as the case may be. Subsequent vacancies in the said offices shall be filled automatically by the other sanggunian members according to their ranking as defined herein.\n(b) A tie between or among the highest ranking sangguniang panlungsod members shall be resolved by drawing of lots.\n(c) The successors as defined herein shall serve only the unexpired terms of their predecessors.\nFor purposes of this Act, a permanent vacancy arises when an elective local official fills a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns or is otherwise permanently incapacitated to discharge the functions of his office.\nFor purposes of succession as provided in this Act, ranking in the sanggunian shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in the City in the immediately preceding local election."}},{"id":"PH-H6201-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Permanent Vacancies in the Sanggunian. — (a) Permanent vacancies in the sangguniang panlungsod where automatic succession as provided above does not apply shall be filled by appointment in the following manner:\n(1) The President, through the Executive Secretary, shall make the aforesaid appointment;\n(2) Only the nominee of the political party under which the sanggunian member concerned had been elected shall be appointed in the manner herein provided. The appointee shall come from the same political party as that of the sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office. In the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be ground for administrative action against the official responsible therefor;\n(3) In case the permanent vacancy is caused by a sanggunian member who does not belong to any political party, the city mayor shall, upon recommendation of the sangguniang panlungsod, appoint a qualified person to fill the vacancy; and\n(4) In case of vacancy in the representation of the youth and the barangay in the sangguniang panlungsod, said vacancy shall be filled automatically by the official next-in-rank of the organization concerned."}},{"id":"PH-H6201-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Temporary Vacancy in the Office of the City Mayor. — (a) When the city mayor is temporarily incapacitated to perform his duties for physical or legal reasons such as, but not limited to, leave of absence, travel abroad, and suspension from office, the city vice-mayor, or the highest ranking sangguniang panlungsod member, shall automatically exercise the powers and perform the duties and functions of the city mayor, except the power to appoint, suspend, or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\n(b) Said temporary incapacity shall terminate upon submission to the sangguniang panlungsod of a written declaration by the city mayor that he has reported back to office. In cases where the temporary incapacity is due to legal causes, the city mayor shall also submit necessary documents showing that said legal causes no longer exist.\n(c) When the city mayor is traveling within the country but outside his territorial jurisdiction for a period not exceeding three (3) consecutive days, he may designate in writing the officer-in-charge of his office. Such authorization shall specify the powers and functions that the local official concerned shall exercise in the absence of the city mayor except the power to appoint, suspend, or dismiss employees.\n(d) In the event, however, that the city mayor fails or refuses to issue such authorization, the city vice-mayor or the highest ranking sangguniang panlungsod member, as the case may be, shall have the right to assume the powers, duties and functions of the said office on the fourth day of absence of the city mayor, subject to the limitations provided in subsection (c) hereof.\n(e) Except as provided above, the city mayor shall in no case authorize any local official to assume the powers, duties, and functions of the office, other than the city vice-mayor, or the highest ranking member of the sangguniang panlungsod, as the case may be.\nARTICLE VII. CITY OFFICERS IN GENERAL"}},{"id":"PH-H6201-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"City Offices. — (a) There shall be established in the city government of the City of Santiago the following offices for its elective officials:\n(1) The Office of the City Mayor;\n(2) The Office of the City Vice-Mayor; and\n(3) The Office of the Members of the Sangguniang Panlungsod.\n(b) The City shall likewise establish the following offices:\n(1) Finance Department — to be composed of the Office of the City Treasurer and Assistant City Treasurer, the Office of the City Assessor and Assistant City Assessor, the Office of the City Accountant, and the Office of the City Budget Officer;\n(2) Health Department — to be composed of the Office of the City Health Officer, the Office of the City Veterinarian, and the Office of the City Environment and Natural Resources Officer;\n(3) Legal Department — to be composed of the Office of the City Legal Officer;\n(4) General Services Department — to be composed of the Office of the City General Services, Office of the City Civil Registrar, Office of the City Administrator, Office of the City Social Welfare and Development Officer, Office of the City Information Officer, Office of the City Population Officer, Office of the City Cooperatives Officer, and the Office of the Secretary of the Sanggunian;\n(5) Planning Department — to be composed of the Office of the City Engineer, Office of the City Architect, and the Office of the City Planning and Development Coordinator.\n(c) The city mayor, as the chief executive of the City, shall have the power to designate the heads of the aforementioned departments, subject to the approval of the members of the sangguniang panlungsod.\nARTICLE VIII. THE APPOINTIVE OFFICIALS OF THE CITY: THEIR QUALIFICATIONS, POWERS AND DUTIES"}},{"id":"PH-H6201-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"The Secretary to the Sangguniang Panlungsod. -\n(1) There shall be a secretary to the sangguniang panlungsod with the rank and salary equal to a head of department or office, who shall be appointed by the city mayor.\n(2) No person shall be appointed secretary to the sangguniang panlungsod unless he is a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in law, commerce or public administration from a recognized college or university, and a first grade civil service eligible or its equivalent.\n(3) The term of the secretary to the sangguniang panlungsod is coterminous with that of the appointing authority.\n(4) The secretary to the sangguniang panlungsod shall take charge of the Office of the Sangguniang Panlungsod and shall:\n(1) Attend meetings of the sangguniang panlungsod and keep a journal of its proceedings;\n(2) Keep the seal of the City and affix the same with his signature to all ordinances, resolutions, and other official acts of the sangguniang panlungsod and present the same to the presiding officer for his signature;\n(3) Forward to the city mayor, for approval, copies of ordinances enacted by the sangguniang panlungsod and duly certified by the presiding officer;\n(4) Furnish, upon request of any interested party, certified copies of records of public character in his custody, upon payment to the city treasurer of such fees as may be prescribed by ordinance;\n(5) Record in a book kept for the purpose all ordinances and resolutions enacted or adopted by the sangguniang panlungsod, with the dates of passage and publication thereof;\n(6) Keep his office and all non-confidential records therein open to the public during the usual business hours;\n(7) Translate into the dialect used by the majority of inhabitants all ordinances and resolutions immediately after their approval, and cause the publication of the same together with the original version in the manner provided for under the Local Government Code; and\n(8) Take custody of the local archives and, where applicable, the local library and annually account for the same; and\n(9) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"The City Treasurer. — (a) The city treasurer shall be appointed by the Secretary of Finance from a list of at least three ranking eligible recommendees of the city mayor, subject to civil service law, rules and regulations.\n(b) The city treasurer shall be under the administration and supervision of the city mayor, to whom he shall report regularly on the tax collection efforts of the City.\n(c) No person shall be appointed treasurer unless he is a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in treasury or accounting service for at least five (5) years in the case of the city treasurer.\n(d) The city treasurer shall receive such compensation, emoluments and allowances as may be determined by law.\n(e) The city treasurer shall take charge of the Treasury Office and shall:\n(1) Advise the city mayor, the sangguniang panlungsod and other local government and national officials concerned regarding disposition of local government funds and such other matters relative to public finance;\n(2) Take custody and exercise proper management of funds of the City;\n(3) Take charge of the disbursement of all funds of the City and such other funds the custody of which may be entrusted to him by law or other competent authority;\n(4) Inspect private commercial and industrial establishments within the jurisdiction of the City in relation to the implementation of tax ordinances, pursuant to the provisions of the Local Government Code;\n(5) Maintain and update the tax information system of the City; and\n(6) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"The Assistant City Treasurer. — (a) The assistant city treasurer may be appointed by the Secretary of Finance from a list of at least three (3) ranking eligible recommendees of the city mayor, subject to civil service law, rules and regulations.\n(b) No person shall be appointed assistant city treasurer unless he is a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in commerce, public administration, or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired at least five (5) years experience in treasury or accounting.\n(c) The assistant city treasurer shall receive such compensation, emoluments and allowances as maybe determined by law.\n(d) The assistant city treasurer shall assist the city treasurer and perform such other duties as the latter may assign him. He shall have authority to administer oaths concerning notices and notifications to those delinquent in the payment of the real property tax and concerning official matter relating to the accounts of the city treasurer or otherwise arising from the offices of the city treasurer and the city assessor."}},{"id":"PH-H6201-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"The City Assessor. — (a) The city assessor must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in real property assessment work or in any related field for at least five (5) years immediately preceding the day of his appointment.\n(b) The city assessor shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city assessor shall take charge of the City Assessor's Office and shall:\n(1) Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purposes are properly executed;\n(2) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purposes;\n(3) Establish a systematic method of real property assessment;\n(4) Install and maintain a real property identification and accounting system;\n(5) Prepare, install and maintain a system of tax mapping, showing graphically all properties subject to assessment and gather all data concerning the same;\n(6) Conduct frequent physical surveys to verify and determine whether all real properties within the City are properly listed in the assessment rolls;\n(7) Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the City;\n(8) Prepare a schedule of the fair market value of the different classes of real properties in accordance with the provisions of the Local Government Code;\n(9) Issue, upon request of any interested party, certified copies of assessment records of real property on all other records relative to its assessment, upon payment of a service charge or fee to the city treasurer;\n(10) Submit every semester a report of all assessments, as well as cancellations and modifications of assessments, to the city mayor and the sangguniang panlungsod; and\n(11) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"The Assistant City Assessor. - (a) The assistant city assessor must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in assessment or in any related field for at least three (3) years immediately preceding the day of his appointment.\n(b) The assistant city assessor shall receive such compensation, emoluments and allowances as maybe determined by law.\n(c) The assistant city assessor shall assist the city assessor and perform such other duties as the latter may assign to him. He shall have the authority to administer oaths on all declarations of real property for purposes of assessment."}},{"id":"PH-H6201-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"The City Accountant. — (a) The city accountant must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, and a certified public accountant. He must have acquired experience in the treasury or accounting service for at least five (5) years immediately preceding the day of his appointment.\n(b) The city accountant shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city accountant shall take charge of both the Office on Accounting and Internal Audit Services and shall:\n(1) Install and maintain an internal audit system in the City;\n(2) Prepare and submit financial statements to the city mayor and to the sangguniang panlungsod;\n(3) Apprise the sangguniang panlungsod and other officials on the financial condition and operations of the City;\n(4) Certify to the availability of budgetary allotment of which expenditures and obligations may be properly charged;\n(5) Review supporting documents before preparation of vouchers to determine completeness of requirements;\n(6) Prepare statements of cash advances, liquidation, salaries, allowances, reimbursements and remittances pertaining to the City;\n(7) Post individual disbursements to the subsidiary ledger and index cards;\n(8) Maintain individual ledgers for officials and employees of the City pertaining to payrolls and deductions;\n(9) Record and post in index cards details of purchased furniture, fixtures and equipment, including disposal thereof, if any;\n(10) Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n(11) Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n(12) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"The City Budget Officer. - (a) The city budget officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in accounting, economics, public administration, or any related course from a recognized college or university and a first grade civil service eligible or its equivalent. He must have acquired experience in government budgeting or in any related field for at least five (5) years immediately preceding the date of his appointment.\n(b) The city budget officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city budget officer shall take charge of the City Budget Office and shall:\n(1) Prepare forms, orders, and circulars embodying instructions on budgetary and appropriation matters for the signature of the city mayor;\n(2) Review and consolidate the budget proposals of different departments and offices of the City;\n(3) Assist the city mayor in the preparation of the budget and during budget hearings;\n(4) Study and evaluate budgetary implications of proposed legislation and submit comments and recommendations thereon;\n(5) Submit periodic budgetary reports to the Department of Budget and Management;\n(6) Coordinate with the city treasurer, the city accountant and the city planning and development coordinator for the purpose of budgeting;\n(7) Assist the sangguniang panlungsod in reviewing the approved budgets of components of the City;\n(8) Coordinate with the city planning and development coordinator in the formulation of the development plan of the City; and\n(9) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"The City Planning and Development Coordinator. — (a) The city planning and development coordinator must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in urban planning, development studies, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in development planning or in any related field for at least five (5) years immediately preceding the date of his appointment.\n(b) The city planning and development coordinator shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city planning and development coordinator shall take charge of the City Planning and Development Office and shall:\n(1) Formulate integrated economic, social, physical, and other development plans and policies for consideration of the City;\n(2) Conduct continuing studies, researches, and training programs necessary to evolve plans and programs for implementation;\n(3) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups of agencies;\n(4) Monitor and evaluate the implementation of the different development programs, projects and activities in the City in accordance with the approved development plan;\n(5) Prepare comprehensive plans and other development planning documents for the consideration of the local development council;\n(6) Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for consideration of the finance committee of the sangguniang panlungsod;\n(7) Promote people participation in development planning within the City; and\n(8) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"The City Engineer. — (a) The city engineer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character and a licensed engineer. He must have acquired experience in the practice of his profession for at least five (5) years immediately preceding the date of his appointment.\n(b) The city engineer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city engineer shall take charge of the City Engineering Office and shall:\n(1) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in infrastructure development and public works in general of the City;\n(2) Advise the city mayor, on infrastructure, public works, and other engineering matters;\n(3) Administer, coordinate, supervise, and control the construction, maintenance, improvement, and repair of roads, bridges, and other engineering and public works projects of the City;\n(4) Provide engineering services to the City, including investigation and survey, engineering designs, feasibility studies and project management; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"The City Health Officer. - (a) The city health officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, and a licensed medical practitioner. He must have acquired experience in the practice of his profession for at least five (5) years immediately preceding the date of his appointment.\n(b) The city health officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city health officer shall take charge of the Office of the City Health Services and shall:\n(1) Supervise the personnel and staff of said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the city mayor, in order to assist him in the efficient, effective and economical implementation of a health services program geared to implement health-related projects and activities;\n(2) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor, in carrying out activities to ensure the delivery of basic services and provision of adequate facilities relative to health service;\n(3) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with health programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(4) Be in the front line of the delivery of health services, particularly during and in the aftermath of man-made and natural disasters and calamities; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"The City Civil Registrar. — (a) The city civil registrar must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in civil registry work at least five (5) years immediately preceding the date of his appointment.\n(b) The city civil registrar shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city civil registrar shall be responsible for the civil registration program in the City of Santiago, pursuant to the Civil Registry Law, the Civil Code, and other pertinent laws, rules and regulations issued to implement them.\n(d) The city civil registrar shall take charge of the Office of the City Civil Registry and shall:\n(1) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with civil registry programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide; and\n(2) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"The City Administrator. — (a) The city administrator must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, holding a college degree preferably in public administration, law, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in management and administration work for at least five (5) years immediately preceding the date of his appointment.\n(b) The city administrator shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city administrator shall take charge of the Office of the City Administrator and shall:\n(1) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the management and administration-related programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(2) Be in the front line of the delivery of administrative support service, particularly those related to the situations during and in the aftermath of man-made and natural disasters and calamities;\n(3) Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to the management and administration of the City; and\n(4) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"The City Legal Officer. — (a) The city legal officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, and a member of the Philippine Bar. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\n(b) The city legal officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city legal officer, the chief legal counsel of the City, shall take charge of the Office for Legal Services and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide legal assistance and support to the city mayor in carrying out the delivery of basic services and provisions of adequate facilities;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with programs and projects related to legal services which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Recommend measures to the sangguniang panlungsod and advise the city mayor on all matters related to upholding the rule of law;\n(4) Be in the front line of protecting human rights and prosecuting any violations thereof, particularly those which occur during and in the aftermath of man-made or natural disasters and calamities; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"The City Social Welfare and Development Officer. — (a) The city social welfare and development officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a duly licensed social worker or a holder of a college degree preferably in sociology or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the practice of social work for at least five (5) years immediately preceding the date of his appointment.\n(b) The city social welfare and development officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city social welfare and development officer shall take charge of the Office on Social Welfare and Development and shall:\n(1) Formulate measures for the approval of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provisions of adequate facilities relative to social welfare and development services;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with social welfare and development programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line of service delivery, particularly those which have to do with immediate relief and assistance during and in the aftermath of man-made and natural disasters and natural calamities;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters related to social welfare and development services which will improve the livelihood and living conditions of the inhabitants; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"The City Environment and Natural Resources Officer. — (a) The city environment and natural resources officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the environmental and natural resources management, conservation, and utilization work for at least five (5) years immediately preceding the date of his appointment.\n(b) The city environment and natural resources officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city government and natural resources officer shall take charge of the Office on Environment and Natural Resources and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to environment and natural resources;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with environment and natural resources programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line of the delivery of services concerning the environment and natural resources, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made and natural disasters and calamities;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all matters relative to the protection, conservation, maximum utilization, application of appropriate technology and other matters related to the environment and natural resources; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"The City Architect. — (a) The city architect must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, and a duly licensed architect. He must have practiced his profession for at least five (5) years immediately preceding the date of his appointment.\n(b) The city architect shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city architect shall take charge of the Office on Architectural Planning and Design and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provisions of adequate facilities relative to architectural planning and design;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with architectural planning and design programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line of the delivery of services involving architectural planning and design, particularly those related to the redesigning of social distribution of basic facilities and physical structures during and in the aftermath of man-made and natural disasters and calamities;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to this architectural planning and design as it relates to the total socioeconomic development of the City; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"The City Information Officer. — (a) The city information officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in journalism, mass communication or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in writing articles and research papers, or in writing for print, television or broadcast media for at least five (5) years immediately preceding the date of his appointment.\n(b) The city information officer shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city information officer shall take charge of the Office on Public Information and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in providing the information and research data required for the delivery of basic services and provision of adequate facilities so that the public becomes aware of said services and may fully avail of the same;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with public information and research data to support programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line in providing information during and in the aftermath of man-made and natural disasters and calamities, with special attention to the victims thereof, to help minimize injuries and casualties during and after the emergency, and to accelerate relief and rehabilitation;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to public information and research data as it relates to the total socioeconomic development of the City; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"The City Cooperatives Officer. — (a) The city cooperatives officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree preferably in business administration with special training in cooperatives or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in cooperatives organization and management for at least five (5) years immediately preceding the date of his appointment.\n(b) The city cooperatives officer shall receive such compensation, emoluments and allowances as maybe determined by law.\n(c) The city cooperatives officer shall take charge of the Office for the Development of Cooperatives and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of facilities through the development of cooperatives, and in providing access to such services and facilities;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the integration of cooperative principles and methods in programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line of cooperatives organization, rehabilitation or viability enhancement, particularly during and in the aftermath of man-made and natural calamities and disasters, to aid in their survival and, if necessary, subsequent rehabilitation;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to cooperatives development and viability enhancement which will improve the livelihood and quality of life of the inhabitants; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"The City Population Officer. — (a) The city population officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree with specialized training in population development from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in the implementation of programs on population development or responsible parenthood for at least three (3) years immediately preceding the date of his appointment.\n(b) The city population officer shall receive such compensation, emoluments and allowances as maybe determined by law.\n(c) The city population officer shall take charge of the Office on Population Development and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to the integration of the population development, principles and in providing access to said services and facilities;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with the integration of population development principles and methods in programs and projects which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide; and\n(3) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and\n(4) those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"The City Veterinarian. — (a) The city veterinarian must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, and a licensed doctor of veterinary medicine. He must have practiced his profession for at least three (3) years immediately preceding the date of his appointment.\n(b) The city veterinarian shall receive such compensation, emoluments and allowances as may be determined by law.\n(c) The city veterinarian shall take charge of the Office of Veterinary Services and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with veterinary-related activities which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Be in the front line of veterinary-related activities, such as the outbreak of highly contagious and deadly diseases and in situations resulting in the depletion of animal for work and human consumption, particularly those arising from and in the aftermath of man-made and natural disasters and calamities;\n(4) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to veterinary services which will increase the number and improve the quality of livestock, poultry and other domestic animals used for work or human consumption; and\n(5) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance."}},{"id":"PH-H6201-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"The City General Services Officer. — (a) The city general services officer must be a citizen of the Philippines, a resident of the City of Santiago, of good moral character, a holder of a college degree on public administration, business administration and management from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in general services, including management of supply, property, solid waste disposal, and general sanitation for at least five (5) years immediately preceding the date of his appointment.\n(b) The city general services officer shall receive such compensation, emoluments and allowances as maybe determined by law.\n(c) The city general services officer shall take charge of the Office on General Services and shall:\n(1) Formulate measures for the consideration of the sangguniang panlungsod and provide technical assistance and support to the city mayor in carrying out measures to ensure the delivery of basic services and provision of adequate facilities which require general services expertise and technical support services;\n(2) Develop plans and strategies, and upon approval thereof by the city mayor, implement the same, particularly those which have to do with general services supportive of the welfare of the inhabitants of the City which the city mayor is empowered to implement and which the sangguniang panlungsod is empowered to provide;\n(3) Take custody of and be accountable for all properties, real or personal, owned by the City, and those granted to it in the form of donation, reparation, assistance and counterpart of joint projects;\n(4) Be in the front line of general services related activities, such as the possible or imminent destruction or damage to records, supplies, properties, and structure materials or debris, particularly during and in the aftermath of man-made and natural disasters and calamities;\n(5) Recommend to the sangguniang panlungsod and advise the city mayor on all other matters relative to general services; and\n(6) Perform such other duties and functions and exercise such other powers as provided for under Republic Act No. 7160, otherwise known as the Local Government Code of 1991, and those that are prescribed by law or ordinance.\nARTICLE IX. THE CITY FIRE STATION SERVICE AND THE CITY JAIL SERVICE"}},{"id":"PH-H6201-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"The City Fire Station Service. — (a) There shall be established in the City at least one (1) fire station with adequate personnel, firefighting facilities and equipment, subject to the standards, rules and regulations as may be promulgated by the Department of the Interior and Local Government. The City shall provide the necessary land or site of the station.\n(b) The city fire station service shall be headed by a city fire marshal whose qualifications shall be as those provided for under Republic Act No. 6975, otherwise known as the PNP Law.\n(c) The city fire station shall be responsible for the fire protection and various emergency services such as rescue and evacuation of injured people at fire-related incidents and, in general, all fire prevention and suppression measures to secure the safety of life and property of the citizenry."}},{"id":"PH-H6201-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"The City Jail Service. — (a) There shall be established and maintained in the City a secured, clean, adequately equipped and sanitary jail for the custody and safekeeping of prisoners, any fugitive from justice, or person detained, awaiting investigation or trial and/or transfer to the national penitentiary, and/or violent mentally ill person who endangers himself or the safety of others, duly certified as such as by the proper medical health officer, pending the transfer to a mental institution.\n(b) The city jail service shall be headed by a city jail warden who must be a graduate of a four (4)-year course in psychology, psychiatry, sociology, nursing, social work or criminology who shall assist in the immediate rehabilitation of individuals or detention of prisoners. Great care must be exercised so that the human rights of these prisoners are respected and protected, and their spiritual and physical well-being are properly and promptly attended to.\nARTICLE X. TRANSITORY AND FINAL PROVISIONS"}},{"id":"PH-H6201-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Municipal Ordinances Existing at the Time of the Approval of this Act. — All municipal ordinances of the Municipality of Santiago existing at the time of the approval of this Act shall continue to be in force within the City of Santiago until the sangguniang panlungsod shall by ordinance provide otherwise."}},{"id":"PH-H6201-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"Plebiscite. — The City of Santiago shall acquire corporate existence upon the ratification of its creation by a majority of the votes cast by the qualified voters in plebiscite to be conducted in the present Municipality of Santiago within sixty (60) days from the approval of this Act. The expenses for such plebiscite shall be borne by the Municipality of Santiago. The Commission on Elections shall conduct and supervise such plebiscite."}},{"id":"PH-H6201-A50","no":50,"noLabel":{"en":"Section 50."},"text":{"en":"Officials of the City of Santiago. — The present elective officials of the Municipality shall continue to exercise their powers and functions until such time that a new election is held and the duly-elected officials shall have already qualified and assumed their offices. Provincial officials of Isabela elected in the May 11, 1992 elections who are residents of the Municipality of Santiago, Isabela, will continue to discharge their respective functions as such until the next local elections, unless otherwise earlier removed for cause. The appointive officials and employees of the Municipality shall likewise continue exercising their functions and duties and they shall be automatically absorbed by the city government of the City of Santiago."}},{"id":"PH-H6201-A51","no":51,"noLabel":{"en":"Section 51."},"text":{"en":"Election of Provincial Governor and Sangguniang Panlalawigan Members for the Province of Isabela. — The qualified voters of the City of Santiago shall not be qualified to vote nor run for any elective position in the elections for provincial governor, vice-governor, sangguniang panlalawigan members and other elective offices for the Province of Isabela."}},{"id":"PH-H6201-A52","no":52,"noLabel":{"en":"Section 52."},"text":{"en":"Representative District. — Until otherwise provided by law, the City of Santiago shall continue to be part of the Fourth Congressional District of Isabela."}},{"id":"PH-H6201-A53","no":53,"noLabel":{"en":"Section 53."},"text":{"en":"Applicability of Laws. — The provision of Republic Act Numbered 7160, otherwise known as the Local Government Code of 1991, Presidential Decree Numbered Eight hundred and twenty-four, and other laws pertaining to the Province of Isabela and such laws as are applicable to cities shall govern the City of Santiago insofar as they are not inconsistent with the provisions of this Act."}},{"id":"PH-H6201-A54","no":54,"noLabel":{"en":"Section 54."},"text":{"en":"Effectivity . — This Act shall take effect upon its approval.\nApproved, May 5, 1994."}}],"pack":"ph-p88"};
  FT["PH-H6202"] = {"id":"PH-H6202","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7721_1994.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"放宽外国银行在菲律宾的准入与经营范围并为其他目的法案","en":"An Act Liberalizing the Entry and Scope of Operations of Foreign Banks in the Philippines and for Other Purposes","orig":"An Act Liberalizing the Entry and Scope of Operations of Foreign Banks in the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7721","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-18","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7721_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6202-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy . — The State shall develop a self-reliant and independent national economy effectively controlled by Filipinos and encourage, promote, and maintain a stable, competitive, efficient, and dynamic banking and financial system that will stimulate economic growth, attract foreign investments, provide a wider variety of financial services to Philippine enterprises, households and individuals, strengthen linkages with global financial centers, enhance the country's competitiveness in the international market and serve as a channel for the flow of funds and investments into the economy to promote industrialization.\nPursuant to this policy, the Philippine banking and financial system is hereby liberalized to create a more competitive environment and encourage greater foreign participation through increase in ownership in domestic banks by foreign banks and the entry of new foreign bank branches.\nIn allowing increased foreign participation in the financial system, it shall be the policy of the State that the financial system shall remain effectively controlled by Filipinos."}},{"id":"PH-H6202-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Modes of Entry. — The Monetary Board may authorize foreign banks to operate in the Philippine banking system through any of the following modes of entry: (i) by acquiring, purchasing or owning up to sixty percent (60%) of the voting stock of an existing bank; (ii) by investing in up to sixty percent (60%) of the voting stock of a new banking subsidiary incorporated under the laws of the Philippines; or (iii) by establishing branches with full banking authority: Provided, That a foreign bank may avail itself of only one (1) mode of entry: Provided, further, That a foreign bank or a Philippine corporation may own up to sixty percent (60%) of the voting stock of only one (1) domestic bank or new banking subsidiary."}},{"id":"PH-H6202-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Guidelines for Approval. — In approving entry applications of foreign banks, the Monetary Board shall: (i) ensure geographic representation and complementation; (ii) consider strategic trade and investment relationships between the Philippines and the country of incorporation of the foreign bank; (iii) study the demonstrated capacity, global reputation for financial innovations and stability in a competitive environment of the applicant; (iv) see to it that reciprocity rights are enjoyed by Philippine banks in the applicant's country; and (v) consider willingness to fully share their technology.\nOnly those among the top one hundred fifty (150) foreign banks in the world or the top five (5) banks in their country of origin as of the date of application shall be allowed entry in accordance with Section 2(ii) and (iii) hereof.\nIn the exercise of this authority, the Monetary Board shall adopt such measures as may be necessary to: (i) ensure that at all times the control of seventy percent (70%) of the resources or assets of the entire banking system is held by domestic banks which are at least majority-owned by Filipinos; (ii) prevent a dominant market position by one bank or the concentration of economic power in one or more financial institutions, or in corporations, partnerships, groups or individuals with related interests; and (iii) secure the listing in the Philippine Stock Exchange of the shares of stocks of banking corporations established under Section 2(i) and (ii) of this Act: Provided, That said banking corporations shall establish stock option plans for their officers and employees as the resources or assets of these corporations may allow in the best business judgment of their respective boards of directors, pursuant to the Corporation Code of the Philippines.\nTo qualify to establish a branch or a subsidiary, the foreign bank applicant must be widely-owned and publicly-listed in its country of origin, unless the foreign bank applicant is owned by the government of its country of origin."}},{"id":"PH-H6202-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Capital Requirements. — (i) For Locally Incorporated Subsidiaries — The minimum capital required for locally incorporated subsidiaries of foreign banks shall be equal to that prescribed by the Monetary Board for domestic banks of the same category.\n(ii) For Foreign Bank Branches — Foreign banks seeking entry pursuant to Section 2(iii) of this Act shall permanently assign capital of not less than the U.S. dollar equivalent of Two hundred ten million pesos (₱210,000,000.00) at the exchange rate on the date of the effectivity of this Act, as ascertained by the Monetary Board. The permanently assigned capital shall be inwardly remitted and converted into Philippine currency. The foreign bank shall be entitled to three (3) branches.\nThe foreign bank may open three (3) additional branches in locations designated by the Monetary Board by inwardly remitting and converting into Philippine currency as permanently assigned capital, the U.S. dollar equivalent of thirty-five million pesos (₱35,000,000.00) per additional branch at the exchange rate on the date of the effectivity of this Act, as ascertained by the Monetary Board. The total number of branches for each new foreign bank entrant shall not exceed six (6).\nFor purposes of meeting the prescribed capital ratios, the term \"capital\" shall include permanently assigned capital plus \"net due to head office, branches and subsidiaries and offices outside the Philippines\" in the ratio prescribed by law or as may be prescribed by the Monetary Board: Provided, That in all cases, the permanently assigned capital and fifteen percent (15%) of \"net due to\" required to comply with prescribed capital ratios shall be inwardly remitted and converted to Philippine currency: Provided, further, That amounts invested in productive enterprises or utilized by Philippine companies for export activities, shall not be subject to conversion into Philippine currency: Provided, finally, That the Monetary Board shall monitor the effective use of the \"net due to\" funds. Whenever there results \"net due from head office\" outside the Philippines, this shall be deducted from the capital accounts for purposes of determining the required capital ratios."}},{"id":"PH-H6202-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Head Office Guarantee. — The head office of foreign bank branches shall guarantee prompt payment of all liabilities of its Philippine branches."}},{"id":"PH-H6202-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Entrants under Section 2(iii). — Foreign banks shall be allowed entry under Section 2(iii) within five (5) years from the effectivity of this Act. During this period, six (6) new foreign banks shall be allowed entry under Section 2(iii) upon the approval of the Monetary Board. An additional four (4) foreign banks may be allowed entry on recommendation of the Monetary Board, subject to compliance with Sections 2, 3, 4, and 5 of this Act, upon approval of the President as the national interest may require."}},{"id":"PH-H6202-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board of Directors. - Non-Filipino citizens maybe come members of the Board of Directors of a bank to the extent of the foreign participation in the equity of said bank."}},{"id":"PH-H6202-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Equal Treatment. - Foreign banks authorized to operate under Section 2 of this Act, shall perform the same functions, enjoy the same privileges, and be subject to the same limitations imposed upon a Philippine bank of the same category. These limits include, among others, the single borrower's limit and capital to risk asset ratio as well as the capitalization required for expanded commercial banking activities under the General Banking Act and other related laws of the Philippines.\nThe basis for computing the ratio shall be the capital of the foreign bank branch in the Philippines.\nThe foreign banks shall guarantee the observance of the rights of their employees under the Constitution.\nAny right, privilege or incentive granted to foreign banks or their subsidiaries or affiliates under this Act, shall be equally enjoyed by and extended under the same conditions to Philippine banks. Philippine corporations whose shares of stocks are listed in the Philippine Stock Exchange or are of long standing for at least ten (10) years shall have the right to acquire, purchase or own up to sixty percent (60%) of the voting stock of a domestic bank."}},{"id":"PH-H6202-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Development Loans Incentives. — Loans extended by a foreign bank's majority-owned subsidiary incorporated under the laws of the Philippines and/or a Philippine bank sixty percent (60%) of the voting stock of which is held by a foreign bank, to finance educational institutions, cooperatives, hospitals and other medical services, socialized or low-cost housing, and to local government units without national government guarantee, shall be included for purposes of determining compliance with the provisions of Presidential Decree No. 717, as amended."}},{"id":"PH-H6202-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Transitory Provisions. - Foreign banks operating through branches in the Philippines upon the effectivity of this Act, shall be eligible for the privilege of establishing up to six (6) additional branches under the same terms and conditions required by Section 4(ii) hereof: Provided, That for any branch additional to what is existing at the time of the effectivity of this Act, the prescribed permanently assigned capital shall be complied with immediately: Provided, further, That a foreign bank may open three (3) branches in the location of its choice and the next three (3) branches in locations designated by the Monetary Board to insure balanced economic development in all the regions.\nThe existing Philippine branches of foreign banks shall be given one-and-a-half (1 1/2) years from the effectivity of this Act to comply with the minimum capital requirements as prescribed under Section 4(ii) of this Act."}},{"id":"PH-H6202-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability Clause . — If any provision of this Act is declared unconstitutional, the same shall not affect the validity of the other provisions not affected thereby."}},{"id":"PH-H6202-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Applicability of Other Banking Laws. — The provisions of Republic Act No. 337, as amended, otherwise known as the General Banking Act, insofar as they are applicable and not in conflict with any provision of this Act, shall apply to banks authorized pursuant to this Act."}},{"id":"PH-H6202-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Delegation of Rule-Making Powers and Compliance Reports. — The Monetary Board is hereby authorized to issue such rules and regulations as may be needed to implement the provisions of this Act after consultation with the chairpersons of the Banks Committee of the House of Representatives and the Senate of the Philippines. On or before May 30 of each year, the Monetary Board shall file a written report to Congress and its respective Banks Committees, on the developments in the implementation of this Act."}},{"id":"PH-H6202-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Amendment and Repeal of Inconsistent Laws. — Sections 11,12,12-A, 12-B, 13,14-A, 21-B, and 68 of Republic Act No. 337, as amended, otherwise known as the General Banking Act; Sections 4 and 5 of Republic Act No. 7353, otherwise known as the Rural Banks Act; Sections 4 and 14 of Republic Act No. 3779, as amended, otherwise known as the Savings and Loan Association Act; and Section 4 of Republic Act No. 4093, as amended, otherwise known as the Private Development Banks Act insofar as they are inconsistent with this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H6202-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days following its publication in the Official Gazette or in two (2) national newspapers of general circulation.\nApproved, May 18, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Liberalizing the Entry and Scope of Operations of Foreign Banks in the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6203"] = {"id":"PH-H6203","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7722_1994.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"设立高等教育委员会、为此拨款并为其他目的法案","en":"An Act Creating the Commission on Higher Education, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Creating the Commission on Higher Education, Appropriating Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7722","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-18","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7722_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 条号自第 2 条起而非自 1 起（止于第 21 条）：本法为“修改型法条”，仅重述被修改的个别条文，条号承被修改法之后，属该体例使然。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6203-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. - The State shall protect, foster and promote the right of all citizens to affordable quality education at all levels and shall take appropriate steps to ensure that education shall be accessible to all. The State shall likewise ensure and protect academic freedom and shall promote its exercise and observance for the continuing intellectual growth, the advancement of learning and research, the development of responsible and effective leadership, the education of high-level and middle-level professionals, and the enrichment of our historical and cultural heritage.\nState-supported institutions of higher learning shall gear their programs to national, regional or local development plans. Finally, all institutions of higher learning shall exemplify through their physical and natural surroundings the dignity and beauty of, as well as their pride in, the intellectual and scholarly life."}},{"id":"PH-H6203-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation of the Commission on Higher Education . - In pursuance of the above mentioned policies, the Commission on Higher Education is hereby created, hereinafter referred to as the Commission.\nThe Commission shall be independent and separate from the Department of Education, Culture and Sports (DECS), and attached to the Office of the President for administrative purposes only. Its coverage shall be both public and private institutions of higher education as well as degree-granting programs in all post-secondary educational institutions, public and private."}},{"id":"PH-H6203-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Composition of the Commission. - The Commission shall be composed of five (5) full-time members. During the transition period which begins upon approval of this Act, the President may appoint the Secretary of Education, Culture and Sports as ex officio chairman of the Commission for a maximum period of one (1) year. Thereafter, the President shall appoint a Chairman of the Commission and four (4) commissioners, who shall be holders of earned doctorate(s), who have been actively engaged in higher education for at least ten (10) years, and must not have been candidates for elective positions in the elections immediately preceding their appointment. They shall be academicians known for their high degree of professionalism and integrity who have distinguished themselves as authorities in their chosen fields of learning. The members of the Commission shall belong to different academic specializations.\nIn no case shall any and all of the Commissioners appoint representatives to act on their behalf."}},{"id":"PH-H6203-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Office. - The President shall appoint the full-time chairman and the commissioners for a term of four (4) years, without prejudice to one reappointment. The terms of the initial appointees shall be on a staggered basis: the full-time chairman shall hold office for a term of four (4) years, the next two (2) commissioners for three (3) years, and the last two (2) commissioners for two (2) years.\nThe commissioners shall hold office until their successors shall have been appointed and qualified. Should a member of the Commission fail to complete his term, his successor shall be appointed by the President of the Philippines but only for the unexpired portion of the term."}},{"id":"PH-H6203-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Rank and Emoluments. - The chairman and the commissioners shall have the rank of a Department Secretary and Undersecretary, respectively. They shall receive the compensation and other emoluments corresponding to those of a Department Secretary and Undersecretary, respectively, and shall be subject to the same disqualifications."}},{"id":"PH-H6203-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board of Advisers. - There shall be constituted a Board of Advisers which shall meet with the Commission at least once a year to assist it in aligning its policies and plans with the cultural, political and socioeconomic development needs of the nation and with the demands of world-class scholarship.\nThe Board of Advisers shall be composed of the following:\na. the Secretary of Education, Culture and Sports, as chairman;\nb. the Director-General of the National Economic and Development Authority, as co-chairman;\nc. the Secretary of Science and Technology;\nd. the Secretary of Trade and Industry;\ne. the Secretary of Labor and Employment;\nf. the President of the Federation of Accrediting Associations of the Philippines (FAAP); and\ng. the President of the Fund for Assistance to Private Education (FAPE).\nTwo (2) additional members of the Board of Advisers may be appointed by the President upon recommendation of the Commission."}},{"id":"PH-H6203-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Powers and Functions of the Commission. -The Commission shall have the following powers and functions:\na. formulate and recommend development plans, policies, priorities, and programs on higher education and research;\nb. formulate and recommend development plans, policies, priorities and programs on research;\nc. recommend to the executive and legislative branches, priorities and grants on higher education and research;\nd. set minimum standards for programs and institutions of higher learning recommended by panels of experts in the field and subject to public hearing, and enforce the same;\ne. monitor and evaluate the performance of programs and institutions of higher learning for appropriate incentives as well as the imposition of sanctions such as, but not limited to, diminution or withdrawal of subsidy, recommendation on the downgrading or withdrawal of accreditation, program termination or school closure;\nf. identify, support and develop potential centers of excellence in program areas needed for the development of world-class scholarship, nation building and national development;\ng. recommend to the Department of Budget and Management the budgets of public institutions of higher learning as well as general guidelines for the use of their income;\nh. rationalize programs and institutions of higher learning and set standards, policies and guidelines for the creation of new ones as well as the conversion or elevation of schools to institutions of higher learning, subject to budgetary limitations and the number of institutions of higher learning in the province or region where creation, conversion or elevation is sought to be made;\ni. develop criteria for allocating additional resources such as research and program development grants, scholarships, and other similar programs: Provided , That these shall not detract from the fiscal autonomy already enjoyed by colleges and universities;\nj. direct or redirect purposive research by institutions of higher learning to meet the needs of agro-industrialization and development;\nk. devise and implement resource development schemes;\nl. administer the Higher Education Development Fund, as described in Section 10 hereunder, which will promote the purposes of higher education;\nm. review the charters of institutions of higher learning and state universities and colleges including the chairmanship and membership of their governing bodies and recommend appropriate measures as basis for necessary action;\nn. promulgate such rules and regulations and exercise such other powers and functions as may be necessary to carry out effectively the purpose and objectives of this Act; and\no. perform such other functions as may be necessary for its effective operations and for the continued enhancement, growth or development of higher education."}},{"id":"PH-H6203-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Secretariat. - The Commission shall organize a secretariat which shall be headed by an executive officer, subject to the national compensation and position classification plan. It shall fix the secretariat’s staffing pattern, determine the duties, qualifications, responsibilities and functions, as well as the compensation scheme for the positions to be created upon the recommendation of the executive officer. It shall also prepare and approve its budget.\nThe Commission shall appoint the members of the staff upon the recommendation of the executive officer."}},{"id":"PH-H6203-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Higher Education Development Fund. -A Higher Education Development Fund, hereinafter referred to as the Fund, is hereby established exclusively for the strengthening of higher education in the entire country.\na. The Government’s contribution to the Fund shall be the following:\n1. the amount of Five hundred million pesos (P500,000,000) as seed capital;\n2. the amount of Fifty million pesos (P50,000,000) for the initial operation of the Commission;\n3. the equivalent of forty percent (40%) annual share on the total gross collections of the travel tax;\n4. the equivalent of thirty percent (30%) share of the collections from the Professional Registration Fee; and\n5. the equivalent of one percent (1%) of the gross sales of the lotto operation of the Philippine Charity Sweepstakes Office (PCSO).\nb. Starting Fiscal Year 1995 and every year thereafter, government financing institutions identified and requested by the Commission may contribute to the Fund an amount equivalent to not less than three percent (3%) but not more than five percent (5%) of their unimpaired surplus realized during the immediately preceding year.\nc. The Fund shall have a private portion to be raised from donations, gifts, and other conveyances including materials, equipment, properties and services by gratuitous title."}},{"id":"PH-H6203-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Management and Administration of the Higher Education Development Fund. - The Fund shall be administered by the Commission. For sound and judicious management of the Fund, the Commission shall appoint a reputable government financial institution as portfolio manager of the Fund, subject to the following conditions.\nAs administrator of the Fund, the Commission shall prepare the necessary guidelines for its use, subject to the following conditions:\na. No part of the seed capital of the Fund, including earnings thereof, shall be used to underwrite overhead expenses for administration;\nb. Unless otherwise stipulated by the private donor, only earnings of private contributions shall be used for administrative expenses;\nc. The Commission shall appoint and organize a separate staff, independent administratively and budgetarily separate from the Commission Secretariat; and\nd. The Fund shall be utilized equitably according to regions and programs."}},{"id":"PH-H6203-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The Technical Panels. - The Commission shall reconstitute and/or organize technical panels for different disciplines/program areas. They shall assist the Commission in setting standards and in program and institution monitoring and evaluation. The technical panels shall be composed of senior specialists or academicians to be appointed by the Commission."}},{"id":"PH-H6203-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Guarantee of Academic Freedom. - Nothing in this Act shall be construed as limiting the academic freedom of universities and colleges. In particular, no abridgment of curricular freedom of the individual educational institutions by the Commission shall be made except for: (a) minimum unit requirements for specific academic programs; (b) general education distribution requirements as may be determined by the Commission; and (c) specific professional subjects as may be stipulated by the various licensing entities. No academic or curricular restriction shall be made upon private educational institutions which are not required for chartered state colleges and universities."}},{"id":"PH-H6203-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Accreditation. - The Commission shall provide incentives to institutions of higher learning, public and private, whose programs are accredited or whose needs are for accreditation purposes."}},{"id":"PH-H6203-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Tax Exemptions. - Any donation, contribution, bequest, and grant which may be made to the Commission shall constitute as allowable deduction from the income of the donor for income tax purposes and shall be exempt from donor’s tax, subject to such conditions as provided under the National Internal Revenue Code, as amended."}},{"id":"PH-H6203-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Authority. - The Commission shall exercise such authority as may be deemed necessary within its premises or areas of operation to effectively carry out its powers and functions and to attain its objectives: Provided , That the Commission may seek the assistance of other government agencies for the proper implementation of this Act."}},{"id":"PH-H6203-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Appropriation. - The amount of Five hundred million pesos (P500,000,000) is hereby authorized to be appropriated for the seed capital of the Fund. The additional amount of Fifty million pesos (P50,000,000) is hereby authorized to be appropriated out of the funds in the National Treasury not otherwise appropriated or out of the Philippine Amusement and Gaming Corporation (PAGCOR) funds for the initial operation of the Commission.\nThe sum equivalent to the appropriations for the current year for the Bureau of Higher Education and the degree-granting-programs of the Bureau of Technical-Vocational Education, including those for higher and tertiary education and degree granting vocational and technical programs of the Bureau of Technical-Vocational Education in the regional offices, as well as parts of the budgetary items under the DECS budget that are concerned with higher and tertiary education and degree-granting vocational and technical programs such as those for personal services, maintenance and other operating expenses and capital outlay, shall be transferred to the Commission.\nThereafter, the funds necessary shall be included in the General Appropriations Act."}},{"id":"PH-H6203-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Transitory Provisions. - Such personnel, properties, assets and liabilities, functions and responsibilities of the Bureau of Higher Education, including those for higher and tertiary education and degree-granting vocational and technical programs in the regional offices, under the Department of Education, Culture and Sports, and other government entities having functions similar to those of the Commission are hereby transferred to the Commission.\nThe Commission shall have the authority to appoint its own personnel.\nAll regular or permanent employees transferred to the Commission shall not suffer any loss of seniority or rank or decrease in emoluments. Personnel of the Bureau of Higher Education not otherwise transferred to the Commission shall be reassigned by the DECS in any of its offices and bureaus: Provided, however, That, any employee who cannot be accommodated shall be given all the benefits as may be provided under existing laws, rules and regulations.\nJurisdiction over DECS-supervised or chartered state-supported post-secondary degree-granting vocational and technical programs and tertiary institutions shall be transferred to the Commission.\nA transitory body is hereby created which shall be composed of the Secretary of Education, Culture and Sports (DECS), Chair of the Senate Committee on Education, Arts and Culture, Chair of the House Committee on Education and Culture, a representative each of the Association of Christian Schools and Colleges (ACSC), the Catholic Educational Association of the Philippines (CEAP), the Philippine Association of Colleges and Universities (PACU), the Philippine Association of Private Schools, Colleges and Universities (PAPSCU), the Philippine Association of State Universities and Colleges (PASUC), and the Philippine Association of Private Technical Institutions (PAPTI).\nThe transitory body shall facilitate the complete and full operation of the Commission which shall not be later than three (3) months after the effectivity of this Act. It shall likewise, promulgate the rules and regulations necessary to effectively implement the smooth and orderly transfer to the Commission. The transition period not exceeding three (3) months shall commence from the approval of this Act."}},{"id":"PH-H6203-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Repealing Clause . -All laws, presidential decrees, executive orders, rules and regulations or parts thereof which are inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6203-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Separability Clause. - If any part or provision of this Act shall be held unconstitutional or invalid, other provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H6203-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Effectivity . - This Act shall take effect upon its approval."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Commission on Higher Education, Appropriating Funds Therefor and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6204"] = {"id":"PH-H6204","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7723_1994.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Delta 广播系统公司在菲律宾境内设立、维护和运营广播电视站的特许经营权法案","en":"An Act Granting the Delta Broadcasting System, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations Within the Philippines","orig":"An Act Granting the Delta Broadcasting System, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations Within the Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7723","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7723_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6204-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. — Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Delta Broadcasting System, Inc., its successors or assigns and hereunder referred to as the grantee, a franchise to construct, establish, maintain and operate, for commercial purposes and in the public interest, radio and television broadcasting stations in the Philippines with the corresponding technological auxiliary equipment, special broadcast, and other broadcast distribution services and relay stations."}},{"id":"PH-H6204-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Right of the Government. — The President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order, may temporarily take over and operate the said stations of the grantee, temporarily suspend the operations of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government upon due compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6204-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Term of Franchise. — This franchise shall be for a term of twenty-five (25) years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that the same shall be void unless the construction of said stations be begun within two (2) years from the date of the approval of this Act and be completed within five (5) years from such date."}},{"id":"PH-H6204-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Prior Approval of the National Telecommunications Commission. — The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6204-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Manner of Operation of Stations or Facilities. — The stations or facilities of the grantee shall be so constructed and operated in a manner as will avoid interference on the wavelengths or frequencies of authorized users, whether for broadcasting or telecommunications purposes, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception of signals."}},{"id":"PH-H6204-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Warranty in Favor of the National and Local Governments. — The grantee shall hold the national, provincial, city, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the grantee."}},{"id":"PH-H6204-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Responsibility to the Public. — The grantee shall provide reasonable public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of public interest; or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6204-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance and Compliance. — Acceptance of this franchise shall be given in writing to the Secretary of Transportation and Communications, with a copy furnished to the chairman of the National Telecommunications Commission, within sixty (60) days after the approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act."}},{"id":"PH-H6204-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. — The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, nor the rights or privileges acquired thereunder to any person, firm, company, partnership, corporation or other commercial or legal entity, nor merge with any other person, firm, company, partnership or corporation not otherwise enfranchised for broadcasting services without the prior approval of the Congress of the Philippines. The controlling interest in the grantee shall not be transferred, assigned nor sold whether as a whole or in parts and whether simultaneously or contemporaneously within five (5) years from the date of the effectivity of this Act. Any corporation to which this franchise may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, partnership, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions, and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, partnership, corporation or other commercial or legal entity."}},{"id":"PH-H6204-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Tax Provisions. — The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise. The grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6204-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Self-regulation by and Undertaking of the Grantee. — The grantee shall not require any prior censorship in any speech, play, act or scene or other matter to be broadcast or telecast from its stations: Provided, That the grantee during any broadcast or telecast may cut off from the air any speech, play, act or scene or other matter being broadcast or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition or the language used therein is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6204-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . — If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6204-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability and Nonexclusivity Clauses. — This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires. This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6204-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. — This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) national newspapers of general circulation in the Philippines.\nApproved, May 19, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Delta Broadcasting System, Inc., a Franchise to Establish, Maintain and Operate Radio and Television Broadcasting Stations Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6205"] = {"id":"PH-H6205","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7724_1994.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"巴科洛德市宪章日","en":"Bacolod City Charter Day","orig":"An Act Declaring October Nineteen of Every Year a Special Nonworking Public Holiday in the City of Bacolod to Be Known as \"Bacolod City Charter Day\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7724","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7724_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6205-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"October Nineteen is the Charter Day Anniversary of the City of Bacolod and its celebration is highlighted, with the staging of the now famous Maskara Festival."}},{"id":"PH-H6205-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"October Nineteen of every year is hereby declared a special nonworking public holiday in the City of Bacolod."}},{"id":"PH-H6205-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 19, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Bacolod City Charter Day","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6206"] = {"id":"PH-H6206","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7725_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将奎松省第四区Atimonan市镇Atimonan第一区国立中学由国立中学改为国立综合中学，名称为Atimonan国立综合中学，并为其运营与维护拨款的法案","en":"An Act Providing for the Change of Status of the Atimonan Zone I National High School in the Municipality of Atimonan, Fourth District of Quezon, From National High School to National Comprehensive High School, to Be Known as the Atimonan National Comprehensive High School, and Appropriating Funds for the Operation and Maintenance Thereof","orig":"An Act Providing for the Change of Status of the Atimonan Zone I National High School in the Municipality of Atimonan, Fourth District of Quezon, From National High School to National Comprehensive High School, to Be Known as the Atimonan National Comprehensive High School, and Appropriating Funds for the Operation and Maintenance Thereof"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7725","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7725_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6206-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Department of Education, Culture and Sports shall cause the change of status of the Atimonan Zone 1 National High School in the Municipality of Atimonan, Fourth District of Quezon, from national high school to national comprehensive high school."}},{"id":"PH-H6206-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The subject school shall be known as the Atimonan National Comprehensive High School."}},{"id":"PH-H6206-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Atimonan Zone 1 National High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6206-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 19, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Change of Status of the Atimonan Zone I National High School in the Municipality of Atimonan, Fourth District of Quezon, From National High School to National Comprehensive High School, to Be Known as the Atimonan National Comprehensive High School, and Appropriating Funds for the Operation and Maintenance Thereof","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6207"] = {"id":"PH-H6207","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7726_1994.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将邦板牙省安赫莱斯市萨潘巴托中学更名为萨潘巴托国立中学并为此拨款的法案","en":"An Act Renaming the Sapangbato High School in Angeles City, Province of Pampanga, as the Sapangbato National High School and Appropriating Funds Thereof","orig":"An Act Renaming the Sapangbato High School in Angeles City, Province of Pampanga, as the Sapangbato National High School and Appropriating Funds Thereof"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7726","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7726_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6207-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sapangbato High School is hereby renamed as the Sapangbato National High School."}},{"id":"PH-H6207-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 19, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renaming the Sapangbato High School in Angeles City, Province of Pampanga, as the Sapangbato National High School and Appropriating Funds Thereof","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6208"] = {"id":"PH-H6208","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7727_1994.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将Tunga描笼涯中学改设为国立中学的法案","en":"An Act Converting the Tunga Barangay High School Into a National High School","orig":"An Act Converting the Tunga Barangay High School Into a National High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7727","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7727_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6208-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tunga Barangay High School in the Municipality of Tunga, Province of Leyte, is hereby converted into a national high school, to be known as the Tunga National High School."}},{"id":"PH-H6208-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 19, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Tunga Barangay High School Into a National High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6209"] = {"id":"PH-H6209","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7728_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sagada市","en":"An Act Converting the Bangaan National High School Annex in Barangay Bangaan, Municipality of Sagada, Mountain Province, Into An Independent National High School, to Be Known as the Bangaan National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Bangaan National High School Annex in Barangay Bangaan, Municipality of Sagada, Mountain Province, Into An Independent National High School, to Be Known as the Bangaan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7728","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-05-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7728_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6209-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bangaan National High School Annex in Barangay Bangaan, Municipality of Sagada, Mountain Province, is hereby separated from the Mountain Province General Comprehensive High School in the Municipality of Bontoc, Mountain Province, and converted into an independent national high school, to be known as the Bangaan National High School."}},{"id":"PH-H6209-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such orders, rules and circulars as may be necessary for the implementation of this Act."}},{"id":"PH-H6209-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Mountain Province General Comprehensive High School Annex in Bangaan, Sagada, Mountain Province. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6209-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, May 19, 1994."}}],"pack":"ph-p88"};
  FT["PH-H6210"] = {"id":"PH-H6210","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7729_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"降低金属与非金属矿物及采石资源消费税税率，为此修订经修正的《国家国内税收法典》第151(A)条的法案","en":"An Act Reducing the Excise Tax Rates on Metallic and Non-metallic Minerals and Quarry Resources, Amending for the Purpose Section 151(A) of the National Internal Revenue Code, as Amended","orig":"An Act Reducing the Excise Tax Rates on Metallic and Non-metallic Minerals and Quarry Resources, Amending for the Purpose Section 151(A) of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7729","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-02","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7729_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6210-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sec. 151(a) of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"Section 151. Mineral Products. - (a) Rates of Tax. - There shall be levied, assessed and collected on mineral, mineral products and quarry resources, excise tax as follows:\n\"(1) On coal and coke, a tax of Ten pesos (₱10) per metric ton.\n\"(2) On all non-metallic minerals and quarry resources, a tax of two percent (2%) based on the actual market value of the annual gross output thereof at the time of removal, in the case of those locally extracted or produced; or the value used by the Bureau of Customs in determining tariff and customs duties, net of excise tax and value-added tax, in the case of importation.\n\"(3) On all metallic minerals, a tax based on the actual market value of the gross output thereof at the time of removal, in the case of those locally extracted or produced; or the value used by the Bureau of Customs in determining tariff and customs duties, net of excise tax and value-added tax, in the case of importation, in accordance with the following schedule:\n\"(a) Copper and other metallic minerals:\n\"(i) On the first three (3) years upon the effectivity of this Act, one percent (1%);\n\"(ii) On the fourth and the fifth year, one and a half percent (1 1/2%); and \"(iii) On the sixth year and thereafter, two percent (2%).\n\"(b) Gold and chromite, two percent (2%).\n\"(4) On indigenous petroleum, a tax of fifteen percent (15%) of the fair international market price thereof, on the first taxable sale, such tax to be paid by the buyer or purchaser within 15 days from the date of actual or constructive delivery to the said buyer or purchaser. The phrase 'first taxable sale, barter, exchange or similar transaction' means the transfer of indigenous petroleum in its original state to a first taxable transferee. The fair international market price shall be determined in consultation with an appropriate government agency.\n\"For the purpose of this subsection, 'indigenous petroleum' shall include locally extracted mineral oil, hydrocarbon gas, bitumen, crude asphalt, mineral gas and all other similar or naturally associated substances with the exception of coal, peat, bituminous shale and/or stratified mineral deposits.\""}},{"id":"PH-H6210-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Finance shall, upon the recommendation of the Commissioner of Internal Revenue, promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6210-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All laws, decrees, orders, rules and regulations, or parts thereof, inconsistent with the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H6210-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, June 2, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reducing the Excise Tax Rates on Metallic and Non-metallic Minerals and Quarry Resources, Amending for the Purpose Section 151(A) of the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6211"] = {"id":"PH-H6211","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7730_1994.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步加强劳动与就业部长的视察与执行权力，为此修订第442号总统令（经修正，即菲律宾劳动法典）第128条（B）款","en":"An Act Further Strengthening the Visitorial and Enforcement Powers of the Secretary of Labor and Employment, Amending for the Purpose Article 128(B) of Presidential Decree Numbered Four Hundred Forty-two as Amended, Otherwise Known as the Labor Code of the Philippines","orig":"An Act Further Strengthening the Visitorial and Enforcement Powers of the Secretary of Labor and Employment, Amending for the Purpose Article 128(B) of Presidential Decree Numbered Four Hundred Forty-two as Amended, Otherwise Known as the Labor Code of the Philippines"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 7730","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-02","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7730_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6211-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (b) of Article 128 of the Labor Code, as amended, is hereby further amended to read as follows:\n\"Art. 128. Visitorial and Enforcement Power. - \"(b) Notwithstanding the provisions of Articles 129 and 217 of this Code to the contrary, and in cases where the relationship of employer-employee still exists, the Secretary of Labor and Employment or his duly authorized representatives shall have the power to issue compliance orders to give effect to the labor standards provisions of this Code and other labor legislation based on the findings of labor employment and enforcement officers or industrial safety engineers made in the course of inspection. The Secretary or his duly authorized representatives shall issue writs of execution to the appropriate authority for the enforcement of their orders, except in cases where the employer contests the findings of the labor employment and enforcement officer and raises issues supported by documentary proofs which were not considered in the course of inspection.\n\"An order issued by the duly authorized representative of the Secretary of Labor and Employment under this article may be appealed to the latter. In case said order involves a monetary award, an appeal by the employer may be perfected only upon the posting of a cash or surety bond issued by a reputable bonding company duly accredited by the Secretary of Labor and Employment in the amount equivalent to the monetary award in the order appealed from.\""}},{"id":"PH-H6211-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws, presidential decrees, executive orders, rules and regulations or parts thereof which are inconsistent with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6211-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in at least two (2) national newspapers of general circulation whichever comes earlier.\nApproved, June 2, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Strengthening the Visitorial and Enforcement Powers of the Secretary of Labor and Employment, Amending for the Purpose Article 128(B) of Presidential Decree Numbered Four Hundred Forty-two as Amended, Otherwise Known as the Labor Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6212"] = {"id":"PH-H6212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7731_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"废除国家大学入学考试（NCEE），为此废止第146号总统法令的法案","en":"An Act Abolishing the National College Entrance Examination (Ncee ), Repealing for the Purpose Presidential Decree Numbered One Hundred Forty-six","orig":"An Act Abolishing the National College Entrance Examination (Ncee ), Repealing for the Purpose Presidential Decree Numbered One Hundred Forty-six"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7731","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-02","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7731_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Presidential Decree Numbered One Hundred Forty -Six (P.D. No. 146) entitled, \"Upgrading the Quality of Education in the Philippines by Requiring All High School Graduates Seeking Admission to Post Secondary Degree Programs Necessitating a Minimum of Four Years Study To Pass a National Entrance Examination and Appropriating Funds Therefor,\" is hereby repealed ."}},{"id":"PH-H6212-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Those who failed the examinations, as required under P.D. No. 146, and failed to make the grade for admissions shall no longer be denied or refused enrollment by any school, college or university to any post-secondary program necessitating a minimum of four (4) years as prescribed under the said Decree subject to the admission requirements of the institutions concerned."}},{"id":"PH-H6212-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"No national entrance examination shall be required for admission to post-secondary degree programs."}},{"id":"PH-H6212-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval .\nApproved, June 2, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Abolishing the National College Entrance Examination (Ncee ), Repealing for the Purpose Presidential Decree Numbered One Hundred Forty-six","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6213"] = {"id":"PH-H6213","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7732_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在北拉瑙省Maigo市镇设立国立中学，名称为Maigo国立中学，并为此拨款的法案","en":"An Act Establishing a National High School in the Municipality of Maigo Province of Lanao Del Norte, to Be Known as the Maigo National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Maigo Province of Lanao Del Norte, to Be Known as the Maigo National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7732","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-03","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7732_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6213-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay Poblacion in the Municipality of Maigo Province of Lanao del Norte, to be known as the Maigo National High School."}},{"id":"PH-H6213-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H6213-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture of Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the Annual General Appropriation Act."}},{"id":"PH-H6213-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 3, 1994."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a National High School in the Municipality of Maigo Province of Lanao Del Norte, to Be Known as the Maigo National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6214"] = {"id":"PH-H6214","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7733_1994.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Quirino市","en":"An Act Establishing a National High School in the Municipality of Quirino, Province of Ilocos Sur, to Be Known as the Quirino National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Quirino, Province of Ilocos Sur, to Be Known as the Quirino National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7733","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-03","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7733_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6214-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Department of Education, Culture and Sports a national high school in the Municipality of Quirino, Province of Ilocos Sur, to be known as the Quirino National High School."}},{"id":"PH-H6214-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6214-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 3, 1994"}}],"pack":"ph-p88"};
