  FT["PH-H6239"] = {"id":"PH-H6239","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7758_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Banaue市","en":"An Act Establishing a National High School in Barangay Gohang, Municipality of Banaue, Province of Ifugao, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Gohang, Municipality of Banaue, Province of Ifugao, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7758","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7758_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6239-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established in Barangay Gohang, Municipality of Banaue, Province of Ifugao, a national high school to be known as Gohang National High School."}},{"id":"PH-H6239-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Gohang National High School shall be under the supervision of the Department of Education, Culture and Sports."}},{"id":"PH-H6239-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6239-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88"};
  FT["PH-H6240"] = {"id":"PH-H6240","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7759_1994.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将大马尼拉拉斯皮纳斯市镇 Pamplona 描笼涯的 Las Piñas 市镇中学 Verdant 附属校改设为名为 Las Piñas East 国立中学的独立中学并拨款","en":"An Act Converting the Las Piñas Municipal High School - Verdant Annex in Barangay Pamplona, Municipality of Las Piñas, Metro Manila, Into An Independent High School, to Be Known as the Las Piñas East National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Las Piñas Municipal High School - Verdant Annex in Barangay Pamplona, Municipality of Las Piñas, Metro Manila, Into An Independent High School, to Be Known as the Las Piñas East National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7759","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7759_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6240-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Las Piñas Municipal High School - Verdant Annex in Barangay Pamplona, Municipality of Las Piñas, Metro Manila, is hereby separated from the Las Piñas Municipal High School in the same municipality and converted into an independent high school, to be known as the Las Piñas East National High School."}},{"id":"PH-H6240-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The present head teacher of the annex school shall act as the principal of the Las Piñas East National High School."}},{"id":"PH-H6240-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the assets, immovable and movable, records, and personnel of the Las Piñas Municipal High School - Verrdant Annex, as well as its liabilities or obligations, are hereby transferred to the Las Piñas East National High School: Provided, however, That the positions, rights, and security of tenure of the personnel therein employed under existing laws are not impaired."}},{"id":"PH-H6240-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6240-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Las Piñas Municipal High School - Verdant Annex in Barangay Pamplona, Municipality of Las Piñas, Metro Manila, Into An Independent High School, to Be Known as the Las Piñas East National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6241"] = {"id":"PH-H6241","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7760_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lumbayanague市","en":"An Act Converting the Nanagun Municipal High School Into Nanagun National High School in Barangay Nanagun, Municipality of Lumbayanague, Province of Lanao Del Sur, and Appropriating Funds Therefor","orig":"An Act Converting the Nanagun Municipal High School Into Nanagun National High School in Barangay Nanagun, Municipality of Lumbayanague, Province of Lanao Del Sur, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7760","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7760_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6241-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be an established national high school in Barangay Nanagun, Municipality of Lumbayanague, Province of Lanao del Sur, by converting the Nanagun Municipal High School into Nanagun National High School."}},{"id":"PH-H6241-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports is hereby directed to take the necessary steps for the immediate conversion, operation and maintenance of the school herein provided."}},{"id":"PH-H6241-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6241-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p88"};
